27	fn password_for(account_id: &str) -> Result<String, String> {
28	    keyring::Entry::new(KEYRING_SERVICE, account_id)
29	        .and_then(|e| e.get_password())
30	        .map_err(|e| format!("No saved password for this account: {e}"))
31	}
32	
33	fn lock(db: &Arc<Mutex<Connection>>) -> std::sync::MutexGuard<'_, Connection> {
34	    db.lock().unwrap_or_else(|p| p.into_inner())
35	}
