1	//! IMAP access to a Gmail (or any IMAP) mailbox, plus MIME parsing into our message shape.
2	
3	use crate::db::NewMessage;
4	use imap::types::{Fetch, Flag, NameAttribute};
5	use mailparse::{MailHeaderMap, ParsedMail};
6	use native_tls::TlsConnector;
7	use std::net::TcpStream;
8	
9	pub type Session = imap::Session<native_tls::TlsStream<TcpStream>>;
10	
11	/// How many of the newest messages to pull on the first sync of a folder.
12	const INITIAL_FETCH: usize = 150;
13	
14	pub fn connect(host: &str, port: u16, email: &str, password: &str) -> Result<Session, String> {
15	    let tls = TlsConnector::builder().build().map_err(|e| e.to_string())?;
16	    let client = imap::connect((host, port), host, &tls).map_err(|e| format!("Could not reach {host}: {e}"))?;
17	    client
18	        .login(email, password)
19	        .map_err(|e| match e.0 {
20	            imap::Error::No(_) | imap::Error::Bad(_) => "Google rejected the sign-in. Check the email and the app password.".to_string(),
21	            other => other.to_string(),
22	        })
23	}
24	
25	/// Server folder names for the roles we care about. Gmail localises "[Gmail]/Sent Mail",
26	/// so we look for the \Sent attribute instead of guessing the name.
27	pub struct Folders {
28	    pub inbox: String,
29	    pub sent: Option<String>,
30	    pub all: Option<String>,
31	    pub trash: Option<String>,
32	}
33	
34	pub fn discover_folders(session: &mut Session) -> Result<Folders, String> {
35	    let names = session.list(None, Some("*")).map_err(|e| e.to_string())?;
36	    let mut f = Folders { inbox: "INBOX".into(), sent: None, all: None, trash: None };
37	    for n in names.iter() {
38	        for a in n.attributes() {
39	            if let NameAttribute::Custom(c) = a {
40	                match c.as_ref() {
41	                    "\\Sent" => f.sent = Some(n.name().to_string()),
42	                    "\\All" => f.all = Some(n.name().to_string()),
43	                    "\\Trash" => f.trash = Some(n.name().to_string()),
44	                    _ => {}
45	                }
46	            }
47	        }
48	    }
49	    Ok(f)
50	}
51	
52	pub struct FolderSync {
53	    pub uid_validity: u32,
54	    /// Every UID currently in the folder (for pruning what was deleted elsewhere).
55	    pub live_uids: Vec<u32>,
56	    /// Flags for UIDs we already had.
57	    pub flags: Vec<(u32, bool, bool)>,
58	    /// Fully fetched new messages.
59	    pub new: Vec<NewMessage>,
60	    pub last_uid: u32,
61	}
62	
63	/// Pull what changed in one folder since `last_uid`. `None` means first sync.
64	pub fn sync_folder(session: &mut Session, server_folder: &str, our_folder: &str, prev: Option<(u32, u32)>) -> Result<FolderSync, String> {
65	    let mailbox = session.select(server_folder).map_err(|e| e.to_string())?;
66	    let uid_validity = mailbox.uid_validity.unwrap_or(0);
67	    let fresh = match prev {
68	        Some((v, _)) if v == uid_validity => false,
69	        _ => true,
70	    };
71	    let last_uid = if fresh { 0 } else { prev.map(|p| p.1).unwrap_or(0) };
72	
73	    let mut live: Vec<u32> = session.uid_search("ALL").map_err(|e| e.to_string())?.into_iter().collect();
74	    live.sort_unstable();
75	
76	    // Which UIDs to fetch in full: everything newer than last_uid, capped on a first sync.
77	    let mut to_fetch: Vec<u32> = live.iter().copied().filter(|u| *u > last_uid).collect();
78	    if fresh && to_fetch.len() > INITIAL_FETCH {
79	        to_fetch = to_fetch[to_fetch.len() - INITIAL_FETCH..].to_vec();
80	    }
81	    // Flags for the ones we already have.
82	    let known: Vec<u32> = live.iter().copied().filter(|u| *u <= last_uid).collect();
83	
84	    let mut flags = Vec::new();
85	    if !known.is_empty() {
86	        let set = known.iter().map(|u| u.to_string()).collect::<Vec<_>>().join(",");
87	        let fetched = session.uid_fetch(set, "(UID FLAGS)").map_err(|e| e.to_string())?;
88	        for f in fetched.iter() {
89	            if let Some(uid) = f.uid {
90	                let (unread, starred) = read_flags(f);
91	                flags.push((uid, unread, starred));
92	            }
93	        }
94	    }
95	
96	    let mut new = Vec::new();
97	    if !to_fetch.is_empty() {
98	        // Fetch in chunks so one huge mailbox doesn't become one huge response.
99	        for chunk in to_fetch.chunks(40) {
100	            let set = chunk.iter().map(|u| u.to_string()).collect::<Vec<_>>().join(",");
101	            let fetched = session
102	                .uid_fetch(set, "(UID FLAGS INTERNALDATE BODY.PEEK[])")
103	                .map_err(|e| e.to_string())?;
104	            for f in fetched.iter() {
105	                if let Some(m) = to_message(f, our_folder) {
106	                    new.push(m);
107	                }
108	            }
109	        }
110	    }
111	
112	    let newest = live.last().copied().unwrap_or(0);
113	    // If the first sync was capped, remember the oldest fetched UID so older mail is not
114	    // mistaken for "new" later; we simply never go further back than the cap for now.
115	    let last = if fresh && !to_fetch.is_empty() { newest } else { newest.max(last_uid) };
116	
117	    Ok(FolderSync { uid_validity, live_uids: if fresh { to_fetch.clone() } else { live }, flags, new, last_uid: last })
118	}
119	
120	fn read_flags(f: &Fetch) -> (bool, bool) {
121	    let mut seen = false;
122	    let mut flagged = false;
123	    for fl in f.flags() {
124	        match fl {
125	            Flag::Seen => seen = true,
126	            Flag::Flagged => flagged = true,
127	            _ => {}
128	        }
129	    }
130	    (!seen, flagged)
131	}
132	
133	fn to_message(f: &Fetch, folder: &str) -> Option<NewMessage> {
134	    let uid = f.uid?;
135	    let raw = f.body()?;
136	    let parsed = mailparse::parse_mail(raw).ok()?;
137	    let (unread, starred) = read_flags(f);
138	
139	    let subject = parsed.headers.get_first_value("Subject").unwrap_or_default();
140	    let subject = if subject.trim().is_empty() { "(no subject)".to_string() } else { subject.trim().to_string() };
141	
142	    let (from_name, from_email) = parsed
