147	        .map(|a| match a {
148	            mailparse::MailAddr::Single(s) => (s.display_name.unwrap_or_default(), s.addr),
149	            mailparse::MailAddr::Group(g) => (g.group_name, String::new()),
150	        })
151	        .unwrap_or_default();
152	    let from_name = if from_name.trim().is_empty() {
153	        from_email.split('@').next().unwrap_or("").to_string()
154	    } else {
155	        from_name.trim().trim_matches('"').to_string()
156	    };
157	
158	    let date = parsed
159	        .headers
160	        .get_first_value("Date")
161	        .and_then(|d| mailparse::dateparse(&d).ok())
162	        .map(|secs| secs * 1000)
163	        .or_else(|| f.internal_date().map(|d| d.timestamp_millis()))
164	        .unwrap_or(0);
165	
166	    let thread_id = thread_key(&parsed, &subject);
167	
168	    let mut text = String::new();
