/** Flip every color token in a CSS text, leaving url(...) contents alone. */
export function flipCss(css: string): string {
  return css
    .split(/(url\([^)]*\))/g)
    .map((part, i) => (i % 2 === 1 ? part : part.replace(COLOR_TOKEN, (t) => flipColor(t))))
    .join("");
}

/** Return the email HTML with all colors flipped for a dark surface. */
export function darkify(html: string): string {
  const doc = new DOMParser().parseFromString(html, "text/html");

  for (const el of Array.from(doc.querySelectorAll<HTMLElement>("*"))) {
    const style = el.getAttribute("style");
    if (style) el.setAttribute("style", flipCss(style));
