38	  const d = new Date(iso);
39	  const diff = (Date.now() - d.getTime()) / 60000;
40	  if (diff < 1) return "now";
41	  if (diff < 60) return Math.round(diff) + "m";
42	  if (diff < 60 * 24) return Math.round(diff / 60) + "h";
43	  if (diff < 60 * 24 * 7) return Math.round(diff / 1440) + "d";
44	  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
45	}
