        let v: serde_json::Value = serde_json::from_str(body.trim_start_matches(")]}'")).map_err(|_| "Google answered in an unexpected format.".to_string())?;
        // ["gaps.login.list", [["gaps.login.account", idx, name, email, photo, gaia, ...], ...]]
