//! Per-account Google sessions.
//!
//! WebView2 allows only one user-data folder per process, so every account's Google window runs
//! in its own helper process (`unimail.exe --google <id> <email> [url]`) with its own cookie jar.
//! That gives each account a fully separate, persistent Google login, independent of every other
//! account and of the user's own browser.
//!
//! The helper does three things:
//!   1. Shows Google in that profile (app-passwords page by default, or a site's OAuth URL).
//!   2. Bounces any non-Google navigation (the site's OAuth callback) to the system browser and
//!      exits, so the site session lands where the user actually browses.
//!   3. Once signed in, fetches the account's display name and profile picture through the
//!      session and writes them to `profiles/<id>/profile.json` for the main app to pick up.

use crate::mail::{account_id_for, MailState};
use base64::Engine;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use tauri::{AppHandle, Emitter, Manager, State, Url, WebviewUrl, WebviewWindowBuilder};
use tauri_plugin_opener::OpenerExt;

const APP_PASSWORDS_URL: &str = "https://myaccount.google.com/apppasswords";
const HELPER_WINDOW: &str = "google";

/// Hosts the Google login flow legitimately bounces through. Anything else is the site's callback.
fn is_google(host: &str) -> bool {
    const ALLOW: &[&str] = &[
        "google.com",
        "googleusercontent.com",
        "gstatic.com",
        "googleapis.com",
        "youtube.com",
        "ggpht.com",
        "googlevideo.com",
        "gvt1.com",
        "recaptcha.net",
    ];
    ALLOW.iter().any(|d| host == *d || host.ends_with(&format!(".{d}")))
}

pub fn profile_dir(app: &AppHandle, account_id: &str) -> Result<PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| e.to_string())?
        .join("profiles")
        .join(account_id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    Ok(dir)
}

#[derive(Serialize, Deserialize)]
struct Profile {
    name: String,
    /// data: URL of the picture.
    avatar: String,
}

// ---------------------------------------------------------------- main-app side

/// Open a Google window for `email`'s profile at `url` (default: the app-passwords page).
#[tauri::command]
pub fn open_google(app: AppHandle, email: String, url: Option<String>) -> Result<(), String> {
    let email = email.trim().to_lowercase();
    let id = account_id_for(&email);
    let target = url.unwrap_or_else(|| APP_PASSWORDS_URL.to_string());
    Url::parse(&target).map_err(|e| format!("Bad link: {e}"))?;
    profile_dir(&app, &id)?;
    let exe = std::env::current_exe().map_err(|e| e.to_string())?;
    std::process::Command::new(exe)
        .args(["--google", &id, &email, &target])
        .spawn()
        .map_err(|e| format!("Could not start the Google window: {e}"))?;
    Ok(())
}

/// Pick up the name and picture the helper wrote after the user signed in. Fails until then.
#[tauri::command]
pub async fn fetch_google_profile(app: AppHandle, state: State<'_, MailState>, account_id: String) -> Result<String, String> {
    let file = profile_dir(&app, &account_id)?.join("profile.json");
    let raw = std::fs::read_to_string(&file).map_err(|_| "Not signed in yet.".to_string())?;
    let p: Profile = serde_json::from_str(&raw).map_err(|e| e.to_string())?;
    let db = state.db.clone();
    let id = account_id.clone();
    let name = p.name.clone();
    let avatar = p.avatar.clone();
    tauri::async_runtime::spawn_blocking(move || -> Result<(), String> {
        let conn = db.lock().unwrap_or_else(|e| e.into_inner());
        crate::db::set_account_avatar(&conn, &id, &avatar).map_err(|e| e.to_string())?;
        // adopt Google's display name if the account still has the automatic one
        if !name.is_empty() {
            let automatic: bool = conn
                .query_row("SELECT name, email FROM accounts WHERE id = ?1", [&id], |r| {
                    let n: String = r.get(0)?;
                    let e: String = r.get(1)?;
                    Ok(n == e.split('@').next().unwrap_or(""))
                })
                .unwrap_or(false);
            if automatic {
                let _ = crate::db::rename_account(&conn, &id, &name);
            }
        }
        Ok(())
    })
    .await
    .map_err(|e| e.to_string())??;
    let _ = app.emit("mail:updated", ());
    Ok(p.avatar)
}

/// Forget an account's Google session entirely.
pub fn remove_profile(app: &AppHandle, account_id: &str) {
    if let Ok(dir) = profile_dir(app, account_id) {
        let _ = std::fs::remove_dir_all(dir);
    }
}

// ---------------------------------------------------------------- helper process

/// Entry point for `unimail.exe --google <id> <email> [url]`.
pub fn run_helper(mut ctx: tauri::Context<tauri::Wry>, args: Vec<String>) {
    let account_id = args.get(2).cloned().unwrap_or_default();
    let email = args.get(3).cloned().unwrap_or_default();
    let url = args.get(4).cloned().unwrap_or_else(|| APP_PASSWORDS_URL.to_string());
    // The helper must not create the main app window.
    ctx.config_mut().app.windows.clear();

    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .setup(move |app| {
            let handle = app.handle().clone();
            let dir = profile_dir(&handle, &account_id)?;
            let target = Url::parse(&url)?;
            let bounce = handle.clone();

            WebviewWindowBuilder::new(app, HELPER_WINDOW, WebviewUrl::External(target))
                .title(format!("Google · {email}"))
                .inner_size(520.0, 780.0)
                .min_inner_size(400.0, 500.0)
                .center()
                .data_directory(dir.clone())
                // plain Chromium args here: no auto-dark for Google's own pages
                .additional_browser_args("--disable-features=msWebOOUI,msPdfOOUI,msSmartScreenProtection")
                .on_navigation(move |u| {
                    let host = u.host_str().unwrap_or("");
                    if u.scheme() == "about" || u.scheme() == "blob" || u.scheme() == "data" || is_google(host) {
                        return true;
                    }
                    // The site's callback: deliver it to the real browser / waiting desktop app, then quit.
                    let _ = bounce.opener().open_url(u.to_string(), None::<&str>);
                    let b = bounce.clone();
                    std::thread::spawn(move || {
                        std::thread::sleep(std::time::Duration::from_millis(300));
                        b.exit(0);
                    });
                    false
                })
                .build()?;

            // Watch for the sign-in to land, then capture the profile once.
            let poller = handle.clone();
            let out = dir.join("profile.json");
            std::thread::spawn(move || loop {
                std::thread::sleep(std::time::Duration::from_secs(3));
                let Some(w) = poller.get_webview_window(HELPER_WINDOW) else { break };
                match probe_profile(&w) {
                    Ok(p) => {
                        if let Ok(json) = serde_json::to_string(&p) {
                            let _ = std::fs::write(&out, json);
                        }
                        break;
                    }
                    Err(_) => continue,
                }
            });
            Ok(())
        })
        .run(ctx)
        .expect("error while running the Google window");
}

/// Ask Google's account-list endpoint (the one Chrome's account picker uses) who is signed in.
fn probe_profile(w: &tauri::WebviewWindow) -> Result<Profile, String> {
    let cookies = w.cookies_for_url(Url::parse("https://accounts.google.com/").unwrap()).map_err(|e| e.to_string())?;
    if cookies.is_empty() {
        return Err("no cookies".into());
    }
    let header = cookies.iter().map(|c| format!("{}={}", c.name(), c.value())).collect::<Vec<_>>().join("; ");
    let client = reqwest::blocking::Client::builder()
        .user_agent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36")
        .build()
        .map_err(|e| e.to_string())?;
    let body = client
        .get("https://accounts.google.com/ListAccounts?gpsia=1&source=ChromiumBrowser&json=standard")
        .header("Cookie", &header)
        .send()
        .and_then(|r| r.text())
        .map_err(|e| e.to_string())?;
    let v: serde_json::Value = serde_json::from_str(body.trim_start_matches(")]}'")).map_err(|_| "unexpected format".to_string())?;
    // ["gaps.login.list", [["gaps.login.account", idx, name, email, photo, gaia, ...], ...]]
    let list = v.get(1).and_then(|l| l.as_array()).ok_or("not signed in")?;
    let me = list
        .iter()
        .find(|a| a.get(0).and_then(|t| t.as_str()) == Some("gaps.login.account"))
        .ok_or("not signed in")?;
    let name = me.get(2).and_then(|x| x.as_str()).unwrap_or("").to_string();
    let photo = me.get(4).and_then(|x| x.as_str()).unwrap_or("").to_string();
    if photo.is_empty() {
        return Ok(Profile { name, avatar: String::new() });
    }
    let photo = match photo.split_once("=s") {
        Some((base, _)) => format!("{base}=s128-c"),
        None => format!("{photo}=s128-c"),
    };
    let bytes = client.get(&photo).send().and_then(|r| r.bytes()).map_err(|e| e.to_string())?;
    let mime = if bytes.len() > 4 && bytes[0] == 0x89 && &bytes[1..4] == b"PNG" { "image/png" } else { "image/jpeg" };
    let avatar = format!("data:{mime};base64,{}", base64::engine::general_purpose::STANDARD.encode(&bytes));
    Ok(Profile { name, avatar })
}

