//! Per-account Google sessions. Each account gets its own WebView2 profile (its own cookie jar)
//! so it stays logged into Google independently of every other account and of the user's browser.
//!
//! Two uses:
//!   1. Adding an account: open Google's app-password page in that profile. Logging in there
//!      creates the persistent session; the app password is created on that same page.
//!   2. "Sign in with Google" chooser: open a site's Google OAuth URL in the chosen account's
//!      profile. Google finishes the login with that account and redirects to the site's callback;
//!      we catch that navigation, hand the callback URL to the user's real browser (where the
//!      site session lives), and close.

use crate::mail::{account_id_for, MailState};
use base64::Engine;
use tauri::{AppHandle, Emitter, Manager, State, Url, WebviewUrl, WebviewWindowBuilder};
use tauri_plugin_opener::OpenerExt;

const APP_PASSWORDS_URL: &str = "https://myaccount.google.com/apppasswords";

/// Hosts the Google login [REDACTED] bounces through. Anything else is the site's callback.
fn is_google(host: &str) -> bool {
    const ALLOW: &[&str] = &[
        "google.com",
        "googleusercontent.com",
        "gstatic.com",
        "googleapis.com",
        "youtube.com",
        "ggpht.com",
        "googlevideo.com",
        "gvt1.com",
        "recaptcha.net",
    ];
    ALLOW.iter().any(|d| host == *d || host.ends_with(&format!(".{d}")))
}

pub fn profile_dir(app: &AppHandle, account_id: &str) -> Result<std::path::PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| e.to_string())?
        .join("profiles")
        .join(account_id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    Ok(dir)
}

/// Open (or focus) the Google window for `email`'s profile at `url`, defaulting to the
/// app-passwords page. Non-Google navigations are bounced to the system browser.
///
/// Deliberately NOT async: on Windows, building a window from an async command deadlocks.
/// A sync command runs on the main thread, which is where windows must be created.
#[tauri::command]
pub fn open_google(app: AppHandle, email: String, url: Option<String>) -> Result<(), String> {
    let email = email.trim().to_lowercase();
    let id = account_id_for(&email);
    let label = format!("google-{id}");
    let target = Url::parse(url.as_deref().unwrap_or(APP_PASSWORDS_URL)).map_err(|e| format!("Bad link: {e}"))?;

    if let Some(w) = app.get_webview_window(&label) {
        w.navigate(target).map_err(|e| e.to_string())?;
        let _ = w.set_focus();
        return Ok(());
    }

    let dir = profile_dir(&app, &id)?;
    let bounce_app = app.clone();
    let bounce_label = label.clone();

    WebviewWindowBuilder::new(&app, &label, WebviewUrl::External(target))
        .title(format!("Google · {email}"))
        .inner_size(520.0, 780.0)
        .min_inner_size(400.0, 500.0)
        .center()
        .data_directory(dir)
        .on_navigation(move |u| {
            let host = u.host_str().unwrap_or("");
            if u.scheme() == "about" || u.scheme() == "blob" || u.scheme() == "data" || is_google(host) {
                return true;
            }
            // The site's callback (https://site/cb?code=…, http://127.0.0.1:port/…, or a custom
            // scheme). Deliver it to the real browser / the waiting desktop app, then close.
            let _ = bounce_app.opener().open_url(u.to_string(), None::<&str>);
            if let Some(w) = bounce_app.get_webview_window(&bounce_label) {
                std::thread::spawn(move || {
                    let _ = w.close();
                });
            }
            false
        })
        .build()
        .map_err(|e| format!("Could not open the Google window: {e}"))?;
    Ok(())
}

/// Forget an account's Google session entirely.
pub fn remove_profile(app: &AppHandle, account_id: &str) {
    if let Ok(dir) = profile_dir(app, account_id) {
        let _ = std::fs::remove_dir_all(dir);
    }
}

/// Name and picture of the Google account signed in inside this account's own window.
/// Uses the same account-list endpoint Chrome's account picker uses, authenticated with the
/// window's cookies. Requires that window to be open (that's where the cookie jar lives).
#[tauri::command]
pub async fn fetch_google_profile(app: AppHandle, state: State<'_, MailState>, account_id: String) -> Result<String, String> {
    let label = format!("google-{account_id}");
    let Some(w) = app.get_webview_window(&label) else {
        return Err("Open the Google window for this account first.".into());
    };
    let url = Url::parse("https://accounts.google.com/").unwrap();
    let cookies = w.cookies_for_url(url).map_err(|e| e.to_string())?;
    if cookies.is_empty() {
        return Err("Not signed in yet.".into());
    }
    let header = cookies.iter().map(|c| format!("{}={}", c.name(), c.value())).collect::<Vec<_>>().join("; ");
    let db = state.db.clone();

    tauri::async_runtime::spawn_blocking(move || -> Result<String, String> {
        let client = reqwest::blocking::Client::builder()
            .user_agent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36")
            .build()
            .map_err(|e| e.to_string())?;
        let body = client
            .get("https://accounts.google.com/ListAccounts?gpsia=1&source=ChromiumBrowser&json=standard")
            .header("Cookie", &header)
            .send()
            .and_then(|r| r.text())
            .map_err(|e| e.to_string())?;
        let v: serde_json::Value = serde_json::from_str(body.trim_start_matches(")]}'")).map_err(|_| "Google answered in an unexpected format.".to_string())?;
        // ["gaps.login.list", [["gaps.login.account", idx, name, email, photo, gaia, ...], ...]]
        let list = v.get(1).and_then(|l| l.as_array()).ok_or("Not signed in yet.")?;
        let me = list.iter().find(|a| a.get(0).and_then(|t| t.as_str()) == Some("gaps.login.account")).ok_or("Not signed in yet.")?;
        let name = me.get(2).and_then(|x| x.as_str()).unwrap_or("").to_string();
        let photo = me.get(4).and_then(|x| x.as_str()).unwrap_or("").to_string();
        if photo.is_empty() {
            return Err("This Google account has no profile picture.".into());
        }
        // ask for a crisp 128px square
        let photo = if photo.contains("=s") { photo.split("=s").next().unwrap_or(&photo).to_string() + "=s128-c" } else { photo + "=s128-c" };
        let bytes = client.get(&photo).send().and_then(|r| r.bytes()).map_err(|e| e.to_string())?;
        let mime = if bytes.len() > 4 && bytes[0] == 0x89 && &bytes[1..4] == b"PNG" { "image/png" } else { "image/jpeg" };
        let data_url = format!("data:{mime};base64,{}", base64::engine::general_purpose::STANDARD.encode(&bytes));
        {
            let conn = db.lock().unwrap_or_else(|p| p.into_inner());
            crate::db::set_account_avatar(&conn, &account_id, &data_url).map_err(|e| e.to_string())?;
            // adopt Google's display name if the account still has the automatic one
            if !name.is_empty() {
                let current: String = conn
                    .query_row("SELECT name, email FROM accounts WHERE id = ?1", [&account_id], |r| {
                        let n: String = r.get(0)?; let e: String = r.get(1)?; Ok(if n == e.split('@').next().unwrap_or("") { String::new() } else { n })
                    })
                    .unwrap_or_default();
                if current.is_empty() {
                    let _ = crate::db::rename_account(&conn, &account_id, &name);
                }
            }
        }
        Ok(data_url)
    })
    .await
    .map_err(|e| e.to_string())?
    .map(|d| { let _ = app.emit("mail:updated", ()); d })
}

