108	fn urlencoding(s: &str) -> String {
109	    let mut out = String::with_capacity(s.len() * 3);
110	    for b in s.bytes() {
111	        match b {
112	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
113	            _ => out.push_str(&format!("%{b:02X}")),
114	        }
115	    }
116	    out
117	}
