122	pub fn installed_browsers() -> Vec<BrowserInfo> {
123	    use winreg::enums::*;
124	    use winreg::RegKey;
125	    let mut out = Vec::new();
126	    for root in [HKEY_LOCAL_MACHINE, HKEY_CURRENT_USER] {
127	        let Ok(clients) = RegKey::predef(root).open_subkey(r"Software\Clients\StartMenuInternet") else { continue };
128	        for name in clients.enum_keys().flatten() {
129	            if name == "UniMail" { continue; }
130	            let Ok(k) = clients.open_subkey(&name) else { continue };
131	            let display: String = k.get_value("").unwrap_or(name.clone());
132	            let Ok(cmd) = k.open_subkey(r"shell\open\command") else { continue };
133	            let raw: String = cmd.get_value("").unwrap_or_default();
134	            let path = raw.trim().trim_matches('"').split('"').next().unwrap_or("").to_string();
135	            if path.is_empty() || out.iter().any(|b: &BrowserInfo| b.path.eq_ignore_ascii_case(&path)) { continue; }
136	            out.push(BrowserInfo { name: display, path });
137	        }
138	    }
139	    out
140	}
