1	//! Per-account Google sessions.
2	//!
3	//! WebView2 allows only one user-data folder per process, so every account's Google window runs
4	//! in its own helper process (`unimail.exe --google <id> <email> [url]`) with its own cookie jar.
5	//! That gives each account a fully separate, persistent Google login, independent of every other
6	//! account and of the user's own browser.
7	//!
8	//! The helper does two things:
9	//!   1. Shows Google in that profile (app-passwords page by default, or a site's OAuth URL).
10	//!   2. Bounces the site's OAuth callback to the user's real browser and exits, so the site
11	//!      session lands where the user actually browses.
12	
13	use crate::mail::account_id_for;
14	use std::path::PathBuf;
15	use tauri::{AppHandle, Manager, Url, WebviewUrl, WebviewWindowBuilder};
16	use tauri_plugin_opener::OpenerExt;
17	
18	const APP_PASSWORDS_URL: &str = "https://myaccount.google.com/apppasswords";
19	const HELPER_WINDOW: &str = "google";
20	
21	/// Hosts the Google login flow legitimately bounces through. Anything else is the site's callback.
22	fn is_google(host: &str) -> bool {
23	    const ALLOW: &[&str] = &[
24	        "google.com",
25	        "googleusercontent.com",
26	        "gstatic.com",
27	        "googleapis.com",
28	        "youtube.com",
29	        "ggpht.com",
30	        "googlevideo.com",
31	        "gvt1.com",
32	        "recaptcha.net",
33	    ];
34	    ALLOW.iter().any(|d| host == *d || host.ends_with(&format!(".{d}")))
35	}
36	
37	/// Only a site's OAuth callback leaves the window: a non-Google http(s) URL carrying an OAuth
38	/// result (`code`/`state`/`error`), a loopback address (desktop apps), or a custom scheme.
39	/// Everything else Google wanders through during sign-in stays inside.
40	fn should_bounce(u: &Url) -> bool {
41	    let scheme = u.scheme();
42	    if scheme == "about" || scheme == "blob" || scheme == "data" {
43	        return false;
44	    }
45	    if scheme != "http" && scheme != "https" {
46	        return true; // custom scheme callback, e.g. com.example.app://oauth
47	    }
48	    let host = u.host_str().unwrap_or("");
49	    if host == "localhost" || host == "127.0.0.1" || host == "[::1]" {
50	        return true;
51	    }
52	    if is_google(host) {
53	        return false;
54	    }
55	    let q = u.query().unwrap_or("");
56	    let frag = u.fragment().unwrap_or("");
57	    let looks_oauth = |s: &str| s.split('&').any(|kv| kv.starts_with("code=") || kv.starts_with("state=") || kv.starts_with("error=") || kv.starts_with("access_token=") || kv.starts_with("id_token="));
58	    looks_oauth(q) || looks_oauth(frag)
59	}
