117	/// Entry point for `unimail.exe --google <id> <email> [url]`.
118	pub fn run_helper(mut ctx: tauri::Context<tauri::Wry>, args: Vec<String>) {
119	    let account_id = args.get(2).cloned().unwrap_or_default();
120	    let email = args.get(3).cloned().unwrap_or_default();
121	    let url = args.get(4).cloned().unwrap_or_else(|| APP_PASSWORDS_URL.to_string());
122	    // The helper must not create the main app window.
123	    ctx.config_mut().app.windows.clear();
124	
125	    tauri::Builder::default()
126	        .plugin(tauri_plugin_opener::init())
127	        .setup(move |app| {
128	            let handle = app.handle().clone();
129	            let dir = profile_dir(&handle, &account_id)?;
130	            let target = Url::parse(&url)?;
131	            let bounce = handle.clone();
132	            let nav_log = dir.join("nav.log");
133	            let _ = &dir;
134	
135	            WebviewWindowBuilder::new(app, HELPER_WINDOW, WebviewUrl::External(target))
136	                .title(format!("Google · {email}"))
137	                .inner_size(520.0, 780.0)
138	                .min_inner_size(400.0, 500.0)
139	                .center()
140	                .data_directory(dir.clone())
141	                // plain Chromium args here: no auto-dark for Google's own pages
142	                .additional_browser_args("--disable-features=msWebOOUI,msPdfOOUI,msSmartScreenProtection")
143	                .on_navigation(move |u| {
144	                    let bouncing = should_bounce(u);
145	                    log_nav(&nav_log, u, bouncing);
146	                    if !bouncing {
147	                        return true;
148	                    }
149	                    // The site's callback: deliver it to the real browser / waiting desktop app, then quit.
150	                    if crate::links::forward(&bounce, u.as_str()).is_err() {
151	                        let _ = bounce.opener().open_url(u.to_string(), None::<&str>);
152	                    }
153	                    let b = bounce.clone();
154	                    std::thread::spawn(move || {
155	                        std::thread::sleep(std::time::Duration::from_millis(300));
156	                        b.exit(0);
157	                    });
158	                    false
159	                })
160	                .build()?;
161	
162	            Ok(())
163	        })
164	        .run(ctx)
165	        .expect("error while running the Google window");
166	}

