        if d < 2 || n - d < 2 { continue; }
        consider(pos, word.to_string(), 40);
    }
    best
}

/// The one-time code in an email, if it looks like one. Subject wins over body.
pub fn find_code(subject: &str, body: &str) -> Option<String> {
