//! Instant mail and verification-code auto-copy.
//!
//! Each account keeps one extra IMAP connection parked in IDLE on its inbox. Gmail pushes a
//! notice the moment a message lands; we sync that account right away, then look through the
//! newly arrived mail for a one-time code. If one is found it goes straight to the clipboard and
//! a Windows notification says so, so the user can paste it without ever opening the app.

use crate::{db, gmail, mail};
use imap::extensions::idle::WaitOutcome;
use regex::Regex;
use rusqlite::Connection;
use std::collections::HashSet;
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, Instant};
use tauri::{AppHandle, Emitter};
use tauri_plugin_notification::NotificationExt;

/// Highest message row id already checked for codes. Mail that was here before the app
/// started is never scanned, so old codes don't get copied on launch.
static SEEN_MAX: AtomicI64 = AtomicI64::new(i64::MAX);

/// Codes are only copied from mail that arrived recently.
const CODE_MAX_AGE_MS: i64 = 15 * 60 * 1000;
/// IDLE is re-issued this often; doubles as a keepalive and an "account removed?" check.
const IDLE_SLICE: Duration = Duration::from_secs(300);

pub fn start(app: AppHandle, dbh: Arc<Mutex<Connection>>) {
    {
        let conn = mail::lock(&dbh);
        let max: i64 = conn.query_row("SELECT COALESCE(MAX(id), 0) FROM messages", [], |r| r.get(0)).unwrap_or(0);
        SEEN_MAX.store(max, Ordering::SeqCst);
    }
    let running: Arc<Mutex<HashSet<String>>> = Arc::default();
    // Supervisor: start a watcher for every account that doesn't have one (new accounts included).
    std::thread::spawn(move || loop {
        let rows = db::all_account_rows(&mail::lock(&dbh)).unwrap_or_default();
        for row in rows {
            let fresh = running.lock().unwrap_or_else(|e| e.into_inner()).insert(row.id.clone());
            if fresh {
                let (app, dbh, running) = (app.clone(), dbh.clone(), running.clone());
                std::thread::spawn(move || {
                    watch(&app, &dbh, &row.id);
                    running.lock().unwrap_or_else(|e| e.into_inner()).remove(&row.id);
                });
            }
        }
        std::thread::sleep(Duration::from_secs(15));
    });
}

/// Keep an IDLE session alive for one account until the account is removed.
fn watch(app: &AppHandle, dbh: &Arc<Mutex<Connection>>, account_id: &str) {
    let mut backoff = Duration::from_secs(5);
    loop {
        let started = Instant::now();
        match idle_session(app, dbh, account_id) {
            Ok(()) => return, // account was removed
            Err(_) => {
                if started.elapsed() > Duration::from_secs(60) {
                    backoff = Duration::from_secs(5);
                }
                std::thread::sleep(backoff);
                backoff = (backoff * 2).min(Duration::from_secs(300));
            }
        }
    }
}

fn idle_session(app: &AppHandle, dbh: &Arc<Mutex<Connection>>, account_id: &str) -> Result<(), String> {
    let Some(acc) = db::get_account(&mail::lock(dbh), account_id).map_err(|e| e.to_string())? else {
        return Ok(());
    };
    let password = mail::password_for(&acc.id)?;
    let mut session = gmail::connect(&acc.imap_host, acc.imap_port, &acc.email, &password)?;
    session.select("INBOX").map_err(|e| e.to_string())?;
    // Catch up on anything that arrived while we weren't listening.
    sync_and_check(app, dbh, &acc);
    loop {
        if db::get_account(&mail::lock(dbh), account_id).map_err(|e| e.to_string())?.is_none() {
            let _ = session.logout();
            return Ok(());
        }
        let outcome = session
            .idle()
            .map_err(|e| e.to_string())?
            .wait_with_timeout(IDLE_SLICE)
            .map_err(|e| e.to_string())?;
        if matches!(outcome, WaitOutcome::MailboxChanged) {
            sync_and_check(app, dbh, &acc);
        }
    }
}

fn sync_and_check(app: &AppHandle, dbh: &Arc<Mutex<Connection>>, acc: &db::AccountRow) {
    if let Ok(added) = mail::sync_account_serial(dbh, acc) {
        if added > 0 {
            let _ = app.emit("mail:updated", ());
        }
    }
    check_codes(app, dbh);
}

/// Look through mail that arrived since the last check for a one-time code.
pub fn check_codes(app: &AppHandle, dbh: &Arc<Mutex<Connection>>) {
    let since = SEEN_MAX.load(Ordering::SeqCst);
    if since == i64::MAX {
        return; // not started yet
    }
    let rows: Vec<(i64, String, String, i64, String)> = {
        let conn = mail::lock(dbh);
        let Ok(mut stmt) = conn.prepare(
            "SELECT id, subject, substr(text_body, 1, 6000), date, from_name FROM messages
             WHERE id > ?1 AND folder = 'inbox' ORDER BY date DESC",
        ) else { return };
        let mapped = stmt.query_map([since], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?)));
        match mapped {
            Ok(it) => it.flatten().collect(),
            Err(_) => return,
        }
    };
    if let Some(max) = rows.iter().map(|r| r.0).max() {
        SEEN_MAX.fetch_max(max, Ordering::SeqCst);
    }
    let cutoff = chrono::Utc::now().timestamp_millis() - CODE_MAX_AGE_MS;
    for (_, subject, body, date, from) in rows {
        if date < cutoff {
            continue;
        }
        if let Some(code) = find_code(&subject, &body) {
            let copied = arboard::Clipboard::new().and_then(|mut c| c.set_text(code.clone())).is_ok();
            let title = if copied { format!("{code} copied") } else { format!("Code {code}") };
            let _ = app.notification().builder().title(title).body(format!("Verification code from {from}")).show();
            let _ = app.emit("otp:copied", code);
            break; // only the newest code
        }
    }
}

// ---------------------------------------------------------------- code detection

const KEYWORDS: &[&str] = &[
    "code", "verification", "verify", "otp", "one-time", "one time", "passcode", "pin", "security code",
    "sign in", "sign-in", "login", "log in", "confirm", "authentication", "2fa", "two-factor", "2-step",
    // ru / uz / tr / es / de / pt / fr
    "код", "подтвержд", "пароль", "kod", "tasdiq", "doğrulama", "código", "verificación", "bestätigung",
    "verifizierung", "confirmação", "vérification",
];

fn keyword_positions(lower: &str) -> Vec<usize> {
    let mut out = Vec::new();
    for kw in KEYWORDS {
        let mut start = 0;
        while let Some(i) = lower[start..].find(kw) {
            let pos = start + i;
            let before_ok = lower[..pos].chars().next_back().map_or(true, |c| !c.is_alphanumeric());
            let after = lower[pos + kw.len()..].chars().next();
            let after_ok = kw.chars().count() > 4 || after.map_or(true, |c| !c.is_alphanumeric() || c == 's');
            if before_ok && after_ok {
                out.push(pos);
            }
            start = pos + kw.len();
        }
    }
    out
}

fn digits_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b(?:[A-Z]{1,3}-)?(\d{3}[ -]\d{3}|\d{4,8})\b").unwrap())
}

/// Best code candidate in one piece of text, with a score (lower is better).
fn best_in(text: &str) -> Option<(usize, String)> {
    let lower = text.to_lowercase();
    let kws = keyword_positions(&lower);
    if kws.is_empty() {
        return None;
    }
    let mut best: Option<(usize, String)> = None;
    let mut consider = |pos: usize, code: String, penalty: usize| {
        let dist = kws
            .iter()
            .map(|&k| if k <= pos { pos - k } else { (k - pos) + 20 })
            .min()
            .unwrap_or(usize::MAX);
        if dist > 250 {
            return;
        }
        let score = dist + penalty;
        if best.as_ref().map_or(true, |(s, _)| score < *s) {
            best = Some((score, code));
        }
    };

    for m in digits_re().find_iter(text) {
        let (s, e) = (m.start(), m.end());
        let prev = text[..s].chars().next_back();
        let next = text[e..].chars().next();
        let next2 = text[e..].chars().nth(1);
        // inside URLs, ids, decimals, money, percentages
        if matches!(prev, Some('/' | '=' | '#' | '&' | '@' | '$' | '€' | '£' | '₽' | '.' | ',')) { continue; }
        if matches!(next, Some('%' | '/' | '=' | '@')) { continue; }
        if matches!(next, Some('.' | ',')) && next2.map_or(false, |c| c.is_ascii_digit()) { continue; }
        let token_start = text[..s].rfind(char::is_whitespace).map_or(0, |i| i + 1);
        let token_end = text[e..].find(char::is_whitespace).map_or(text.len(), |i| e + i);
        let token = &text[token_start..token_end];
        if token.contains("http") || token.contains("www.") || token.contains('/') { continue; }
        let around = &lower[s.saturating_sub(6)..s];
        if around.contains("usd") || around.contains("uzs") || around.contains("sum") || around.contains("so'm") { continue; }

        let digits: String = m.as_str().chars().filter(|c| c.is_ascii_digit()).collect();
        let mut penalty = if digits.len() == 6 { 0 } else { 15 };
        if digits.len() == 4 {
            if let Ok(n) = digits.parse::<u32>() {
                if (1900..=2100).contains(&n) { penalty += 80; }
            }
        }
        consider(s, digits, penalty);
    }

    // Alphanumeric codes like K7Q2XP: 6-8 uppercase letters/digits with at least two of each.
    let mut offset = 0;
    for word in text.split(|c: char| !c.is_alphanumeric()) {
        let pos = text[offset..].find(word).map_or(offset, |i| offset + i);
        offset = pos + word.len();
        let n = word.chars().count();
        if !(6..=8).contains(&n) || !word.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit()) { continue; }
        let d = word.chars().filter(|c| c.is_ascii_digit()).count();
        if d < 2 || n - d < 2 { continue; }
        consider(pos, word.to_string(), 40);
    }
    best
}

/// The one-time code in an email, if it looks like one. Subject wins over body.
pub fn find_code(subject: &str, body: &str) -> Option<String> {
    if let Some((_, c)) = best_in(subject) {
        return Some(c);
    }
    best_in(body).map(|(_, c)| c)
}

#[cfg(test)]
mod tests {
    use super::find_code;

    #[test]
    fn common_shapes() {
        assert_eq!(find_code("G-482913 is your Google verification code", ""), Some("482913".into()));
        assert_eq!(find_code("Your code", "Your verification code is 123 456. It expires in 10 minutes."), Some("123456".into()));
        assert_eq!(find_code("Sign in to Steam", "Here is the Steam Guard code you need: K7Q2XP"), Some("K7Q2XP".into()));
        assert_eq!(find_code("Ваш код", "Код подтверждения: 5521"), Some("5521".into()));
        assert_eq!(find_code("Login attempt", "Use 849201 to log in. https://example.com/a/123456"), Some("849201".into()));
    }

    #[test]
    fn not_codes() {
        assert_eq!(find_code("Your order", "Total 1499.00 USD, order 20260911"), None);
        assert_eq!(find_code("Weekly digest", "In 2026 we shipped 1234 features"), None);
        assert_eq!(find_code("Receipt", "Paid $4999 for your subscription code red"), None);
    }
}

