Add-Type @'
using System; using System.Runtime.InteropServices;
public class UX {
  [StructLayout(LayoutKind.Sequential)] public struct R { public int L,T,Rt,B; }
  [StructLayout(LayoutKind.Sequential)] public struct P { public int X,Y; }
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out R r);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr WindowFromPoint(P p);
  [DllImport("user32.dll")] public static extern IntPtr GetAncestor(IntPtr h, uint f);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetCursorPos(out P p);
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
  [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, UIntPtr e);
  [DllImport("user32.dll")] public static extern void keybd_event(byte k, byte s, uint f, UIntPtr e);
}
'@
$p = Get-Process unimail | Where-Object MainWindowHandle -ne 0 | Select-Object -First 1
$h = $p.MainWindowHandle
"visible before: $([UX]::IsWindowVisible($h))"
[UX]::keybd_event(0x12,0,0,[UIntPtr]::Zero); [UX]::SetForegroundWindow($h) | Out-Null; [UX]::keybd_event(0x12,0,2,[UIntPtr]::Zero)
Start-Sleep -Milliseconds 700
$r = New-Object UX+R; [UX]::GetWindowRect($h,[ref]$r) | Out-Null
$pt = New-Object UX+P; $pt.X = $r.Rt - 23; $pt.Y = $r.T + 20   # center of the 46x40 close button
$under = [UX]::GetAncestor([UX]::WindowFromPoint($pt), 2)
if ($under -ne $h) { "SKIPPED: another window covers the X, not clicking"; return }
$old = New-Object UX+P; [UX]::GetCursorPos([ref]$old) | Out-Null
[UX]::SetCursorPos($pt.X,$pt.Y) | Out-Null; Start-Sleep -Milliseconds 150
[UX]::mouse_event(0x2,0,0,0,[UIntPtr]::Zero); [UX]::mouse_event(0x4,0,0,0,[UIntPtr]::Zero)
Start-Sleep -Milliseconds 900
[UX]::SetCursorPos($old.X,$old.Y) | Out-Null
"visible after click on X: $([UX]::IsWindowVisible($h))"
"process still running: $([bool](Get-Process unimail -ErrorAction SilentlyContinue))"

