$src = "$env:TEMP\UniMail.installer.lnk"   # the installer's original shortcut, with UniMail's app id
if (-not (Test-Path $src)) { $src = "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\UniMail.lnk" }
$dst = "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\UniMail.lnk"
$cmd = "Copy-Item -LiteralPath '$src' -Destination '$dst' -Force"
try {
  Start-Process powershell -Verb RunAs -WindowStyle Hidden -Wait -ArgumentList "-NoProfile -Command $cmd"
} catch { "permission prompt was declined or failed: $($_.Exception.Message)" }
"all-users Start menu shortcut present: $(Test-Path $dst)"
if (Test-Path $dst) {
  Remove-Item "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\UniMail.lnk" -ErrorAction SilentlyContinue   # avoid a duplicate entry
  $ws = New-Object -ComObject WScript.Shell; "points to: $($ws.CreateShortcut($dst).TargetPath)"
}

