import { Search, Star, PenLine } from "lucide-react";
import type { Account, Message } from "../data/mock";
import { Avatar } from "./Avatar";
import "./MailList.css";

type Folder = Message["folder"];

interface Props {
  title: string;
  accountsById: Record<string, Account>;
  messages: Message[];
  folder: Folder;
  onFolder: (f: Folder) => void;
  selectedId: string | null;
  onSelect: (id: string) => void;
  showAccountChip: boolean;
}

const folders: { id: Folder; label: string }[] = [
  { id: "inbox", label: "Inbox" },
  { id: "starred", label: "Starred" },
  { id: "sent", label: "Sent" },
  { id: "archive", label: "Archive" },
];

export function relTime(iso: string) {
  const d = new Date(iso);
  const diff = (Date.now() - d.getTime()) / 60000;
  if (diff < 60) return Math.max(1, Math.round(diff)) + "m";
  if (diff < 60 * 24) return Math.round(diff / 60) + "h";
  if (diff < 60 * 24 * 7) return Math.round(diff / 1440) + "d";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

export function MailList({ title, accountsById, messages, folder, onFolder, selectedId, onSelect, showAccountChip }: Props) {
  return (
    <section className="list">
      <header className="list-head">
        <div className="list-title-row">
          <h1 className="list-title">{title}</h1>
          <button className="compose" title="Compose">
            <PenLine size={16} strokeWidth={2.4} />
            <span>Compose</span>
          </button>
        </div>
        <label className="search">
          <Search size={16} />
          <input placeholder="Search all mail" />
        </label>
        <div className="folders">
          {folders.map((f) => (
            <button key={f.id} className="pill" data-active={folder === f.id} onClick={() => onFolder(f.id)}>
              {f.label}
            </button>
          ))}
        </div>
      </header>

      <div className="list-scroll">
        {messages.length === 0 && <div className="list-empty">Nothing here. Enjoy the quiet.</div>}
        {messages.map((m) => {
          const acc = accountsById[m.accountId];
          return (
            <button key={m.id} className="row" data-selected={selectedId === m.id} data-unread={m.unread} onClick={() => onSelect(m.id)}>
              <Avatar name={m.from.name} hue={acc.hue} size={40} />
              <div className="row-body">
                <div className="row-top">
                  <span className="row-from">{m.from.name}</span>
                  {showAccountChip && (
                    <span className={"row-chip hue-" + acc.hue} title={acc.email}>{acc.name}</span>
                  )}
                  <span className="row-time">{relTime(m.date)}</span>
                </div>
                <div className="row-subject">{m.subject}</div>
                <div className="row-preview">{m.preview}</div>
              </div>
              {m.starred && <Star size={14} className="row-star" fill="currentColor" />}
              {m.unread && <span className="row-dot" />}
            </button>
          );
        })}
      </div>
    </section>
  );
}

.list {
  width: 400px; min-width: 340px; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface);
  border-radius: var(--r-xl) 0 0 var(--r-xl);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}
.list-head { padding: 22px 18px 10px; display: flex; flex-direction: column; gap: 12px; }
.list-title-row { display: flex; align-items: center; justify-content: space-between; }
.list-title { margin: 0; font-family: var(--font-display); font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }

.compose {
  display: inline-flex; align-items: center; gap: 8px;
  height: 36px; padding: 0 14px 0 12px; border-radius: var(--r-pill);
  background: var(--ink); color: var(--bg); font-weight: 600;
  box-shadow: var(--shadow-1);
  transition: transform var(--t-med) var(--ease-spring), box-shadow var(--t-med);
}
.compose:hover { transform: translateY(-1px); box-shadow: var(--shadow-2); }
.compose:active { transform: scale(0.97); }

.search {
  display: flex; align-items: center; gap: 10px;
  height: 40px; padding: 0 14px; border-radius: var(--r-md);
  background: var(--surface-2); color: var(--ink-3);
  transition: box-shadow var(--t-fast), background var(--t-fast);
}
.search:focus-within { background: var(--surface); box-shadow: 0 0 0 2px var(--accent); color: var(--ink-2); }
.search input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); }
.search input::placeholder { color: var(--ink-3); }

.folders { display: flex; gap: 4px; }

.list-scroll { flex: 1; overflow-y: auto; padding: 4px 10px 16px; }
.list-empty { padding: 60px 20px; text-align: center; color: var(--ink-3); }

.row {
  position: relative; width: 100%; text-align: left;
  display: flex; gap: 12px; align-items: flex-start;
  padding: 12px 12px; border-radius: var(--r-md);
  transition: background var(--t-fast) var(--ease);
}
.row:hover { background: var(--surface-2); }
.row[data-selected="true"] { background: var(--surface-3); }
.row-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.row-top { display: flex; align-items: center; gap: 8px; }
.row-from { font-weight: 600; color: var(--ink-2); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row[data-unread="true"] .row-from { color: var(--ink); }
.row-time { font-size: 12px; color: var(--ink-3); flex-shrink: 0; }
.row-chip {
  font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 99px; flex-shrink: 0;
  color: var(--a2); background: color-mix(in srgb, var(--a1) 18%, transparent);
}
.row-subject { font-weight: 500; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row[data-unread="true"] .row-subject { font-weight: 700; color: var(--ink); }
.row-preview { font-size: 13px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-star { position: absolute; right: 14px; bottom: 14px; color: #f2b234; }
.row-dot { position: absolute; left: 4px; top: 50%; width: 6px; height: 6px; margin-top: -3px; border-radius: 50%; background: var(--accent); }

import { Archive, Reply, Star, Trash2, MailOpen, Forward } from "lucide-react";
import type { Account, Message } from "../data/mock";
import { Avatar } from "./Avatar";
import "./Reader.css";

interface Props {
  message: Message | null;
  account: Account | null;
}

export function Reader({ message, account }: Props) {
  if (!message || !account) {
    return (
      <section className="reader reader-empty">
        <div className="reader-empty-art">
          <MailOpen size={38} strokeWidth={1.6} />
        </div>
        <p>Pick a message to read it here.</p>
      </section>
    );
  }
  const date = new Date(message.date);
  return (
    <section className="reader">
      <header className="reader-bar">
        <div className={"reader-account hue-" + account.hue}>
          <Avatar name={account.name} hue={account.hue} size={22} />
          <span>{account.email}</span>
        </div>
        <div className="reader-actions">
          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
          <button className="icon-btn" title="Star"><Star size={18} /></button>
          <button className="icon-btn" title="Archive"><Archive size={18} /></button>
          <button className="icon-btn" title="Delete"><Trash2 size={18} /></button>
        </div>
      </header>

      <article className="reader-card">
        <h2 className="reader-subject">{message.subject}</h2>
        <div className="reader-from">
          <Avatar name={message.from.name} hue={account.hue} size={44} />
          <div className="reader-from-text">
            <div className="reader-from-name">{message.from.name}</div>
            <div className="reader-from-email">{message.from.email}</div>
          </div>
          <div className="reader-date">
            {date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" })}
            <br />
            {date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" })}
          </div>
        </div>
        <div className="reader-body">{message.body}</div>
      </article>
    </section>
  );
}

.reader {
  flex: 1; min-width: 0; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface-2);
  overflow: hidden;
}
.reader-empty { align-items: center; justify-content: center; gap: 14px; color: var(--ink-3); }
.reader-empty-art {
  display: grid; place-items: center; width: 84px; height: 84px; border-radius: 38%;
  background: var(--surface); color: var(--ink-3); box-shadow: var(--shadow-1);
}

.reader-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 20px 6px;
}
.reader-account {
  display: inline-flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 12px 0 5px; border-radius: var(--r-pill);
  background: var(--surface); color: var(--ink-2); font-size: 13px; font-weight: 500;
  box-shadow: var(--shadow-1);
}
.reader-actions { display: flex; gap: 2px; }

.reader-card {
  flex: 1; margin: 8px 20px 20px; padding: 28px 32px;
  background: var(--surface); border-radius: var(--r-xl);
  box-shadow: var(--shadow-1);
  overflow-y: auto; user-select: text;
}
.reader-subject { margin: 0 0 22px; font-family: var(--font-display); font-size: 24px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.25; }
.reader-from { display: flex; align-items: center; gap: 14px; padding-bottom: 20px; border-bottom: 1px solid var(--border); }
.reader-from-text { flex: 1; }
.reader-from-name { font-weight: 700; }
.reader-from-email { font-size: 13px; color: var(--ink-3); }
.reader-date { font-size: 12px; color: var(--ink-3); text-align: right; line-height: 1.5; }
.reader-body { padding-top: 22px; white-space: pre-wrap; font-size: 15px; line-height: 1.65; color: var(--ink); max-width: 68ch; }

import { useState } from "react";
import { X, Link2, Mail, ArrowRight, ShieldCheck } from "lucide-react";
import type { Account } from "../data/mock";
import { Avatar } from "./Avatar";
import "./AddSheet.css";

interface Props {
  accounts: Account[];
  onClose: () => void;
}

type Tab = "signin" | "add";

function looksLikeGoogleAuth(url: string) {
  try {
    const u = new URL(url.trim());
    return u.hostname === "accounts.google.com" && u.pathname.includes("/o/oauth2");
  } catch {
    return false;
  }
}

export function AddSheet({ accounts, onClose }: Props) {
  const [tab, setTab] = useState<Tab>("signin");
  const [url, setUrl] = useState("");
  const [picked, setPicked] = useState<string | null>(null);
  const valid = looksLikeGoogleAuth(url);
  const google = accounts.filter((a) => a.provider === "gmail");

  return (
    <div className="sheet-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="sheet" role="dialog" aria-modal>
        <header className="sheet-head">
          <div className="sheet-tabs">
            <button className="pill" data-active={tab === "signin"} onClick={() => setTab("signin")}>
              <ShieldCheck size={15} /> Sign in with Google
            </button>
            <button className="pill" data-active={tab === "add"} onClick={() => setTab("add")}>
              <Mail size={15} /> Add account
            </button>
          </div>
          <button className="icon-btn" onClick={onClose} title="Close"><X size={18} /></button>
        </header>

        {tab === "signin" && (
          <div className="sheet-body">
            <h2 className="sheet-title">Which account should sign in?</h2>
            <p className="sheet-hint">
              Paste the Google sign-in link a site or app just opened. UniMail finishes the login with the account you pick and
              hands the result back to your browser, so nothing else changes.
            </p>
            <label className="sheet-field" data-valid={url ? valid : undefined}>
              <Link2 size={16} />
              <input
                autoFocus
                placeholder="https://accounts.google.com/o/oauth2/..."
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                spellCheck={false}
              />
            </label>

            <div className="sheet-grid">
              {google.map((a) => (
                <button key={a.id} className="acct" data-picked={picked === a.id} onClick={() => setPicked(a.id)}>
                  <Avatar name={a.name} hue={a.hue} size={44} />
                  <div className="acct-text">
                    <div className="acct-name">{a.name}{a.owner === "friend" && <span className="acct-tag">friend</span>}</div>
                    <div className="acct-email">{a.email}</div>
                  </div>
                </button>
              ))}
            </div>

            <button className="primary" disabled={!valid || !picked}>
              Continue <ArrowRight size={16} />
            </button>
          </div>
        )}

        {tab === "add" && (
          <div className="sheet-body">
            <h2 className="sheet-title">Connect a mailbox</h2>
            <p className="sheet-hint">Gmail, Outlook, iCloud, or any IMAP host. It stays signed in until you remove it.</p>
            <div className="providers">
              {[
                ["Gmail", "coral"],
                ["Outlook", "sky"],
                ["iCloud", "slate"],
                ["Other IMAP", "grape"],
              ].map(([label, hue]) => (
                <button key={label} className={"provider hue-" + hue}>
                  <span className="provider-dot" />
                  {label}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

.sheet-backdrop {
  position: fixed; inset: 0; z-index: 50;
  display: grid; place-items: center;
  background: rgba(30, 20, 10, 0.32);
  backdrop-filter: blur(6px);
  animation: fade var(--t-med) var(--ease);
}
@keyframes fade { from { opacity: 0; } }
@keyframes pop { from { opacity: 0; transform: translateY(14px) scale(0.98); } }

.sheet {
  width: 560px; max-width: calc(100vw - 40px);
  background: var(--surface); border-radius: var(--r-xl);
  box-shadow: var(--shadow-3);
  animation: pop 260ms var(--ease-spring);
  overflow: hidden;
}
.sheet-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 14px 0 18px; }
.sheet-tabs { display: flex; gap: 4px; }
.sheet-body { padding: 18px 26px 26px; display: flex; flex-direction: column; gap: 14px; }
.sheet-title { margin: 6px 0 0; font-family: var(--font-display); font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }
.sheet-hint { margin: 0; color: var(--ink-2); line-height: 1.5; }

.sheet-field {
  display: flex; align-items: center; gap: 10px;
  height: 44px; padding: 0 14px; border-radius: var(--r-md);
  background: var(--surface-2); color: var(--ink-3);
  transition: box-shadow var(--t-fast), background var(--t-fast);
}
.sheet-field:focus-within { background: var(--surface); box-shadow: 0 0 0 2px var(--accent); }
.sheet-field[data-valid="true"] { box-shadow: 0 0 0 2px #2fb36b; }
.sheet-field[data-valid="false"] { box-shadow: 0 0 0 2px #e5484d; }
.sheet-field input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); font-size: 13px; }

.sheet-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.acct {
  display: flex; align-items: center; gap: 12px; text-align: left;
  padding: 10px 12px; border-radius: var(--r-md);
  background: var(--surface-2);
  border: 2px solid transparent;
  transition: border-color var(--t-fast), background var(--t-fast), transform var(--t-med) var(--ease-spring);
}
.acct:hover { background: var(--surface-3); }
.acct:active { transform: scale(0.98); }
.acct[data-picked="true"] { border-color: var(--ink); background: var(--surface); }
.acct-text { min-width: 0; }
.acct-name { font-weight: 700; display: flex; align-items: center; gap: 6px; }
.acct-tag { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--ink-3); background: var(--surface-3); padding: 1px 6px; border-radius: 99px; }
.acct-email { font-size: 12px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.primary {
  align-self: flex-end;
  display: inline-flex; align-items: center; gap: 8px;
  height: 42px; padding: 0 18px 0 20px; border-radius: var(--r-pill);
  background: var(--accent); color: var(--accent-ink); font-weight: 600;
  box-shadow: var(--shadow-1);
  transition: transform var(--t-med) var(--ease-spring), opacity var(--t-fast);
}
.primary:hover { transform: translateY(-1px); }
.primary:disabled { opacity: 0.4; cursor: not-allowed; transform: none; }

.providers { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.provider {
  display: flex; align-items: center; gap: 12px;
  height: 56px; padding: 0 16px; border-radius: var(--r-md);
  background: var(--surface-2); font-weight: 600;
  transition: background var(--t-fast), transform var(--t-med) var(--ease-spring);
}
.provider:hover { background: var(--surface-3); transform: translateY(-1px); }
.provider-dot { width: 22px; height: 22px; border-radius: 38%; background: linear-gradient(135deg, var(--a1), var(--a2)); }

import { useMemo, useState } from "react";
import { accounts, messages, type Message } from "./data/mock";
import { AccountRail } from "./components/AccountRail";
import { MailList } from "./components/MailList";
import { Reader } from "./components/Reader";
import { AddSheet } from "./components/AddSheet";
import "./styles/base.css";
import "./App.css";

type Folder = Message["folder"];

export default function App() {
  const [selectedAccount, setSelectedAccount] = useState<string | "all">("all");
  const [folder, setFolder] = useState<Folder>("inbox");
  const [selectedMsg, setSelectedMsg] = useState<string | null>(null);
  const [sheet, setSheet] = useState(false);

  const accountsById = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a])), []);

  const visible = useMemo(() => {
    return messages
      .filter((m) => selectedAccount === "all" || m.accountId === selectedAccount)
      .filter((m) => (folder === "starred" ? m.starred : m.folder === folder))
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [selectedAccount, folder]);

  const current = visible.find((m) => m.id === selectedMsg) ?? null;
  const title = selectedAccount === "all" ? "All inboxes" : accountsById[selectedAccount].name;

  return (
    <div className="app">
      <AccountRail
        accounts={accounts}
        selected={selectedAccount}
        onSelect={(id) => { setSelectedAccount(id); setSelectedMsg(null); }}
        onAdd={() => setSheet(true)}
      />
      <main className="main">
        <MailList
          title={title}
          accountsById={accountsById}
          messages={visible}
          folder={folder}
          onFolder={setFolder}
          selectedId={selectedMsg}
          onSelect={setSelectedMsg}
          showAccountChip={selectedAccount === "all"}
        />
        <Reader message={current} account={current ? accountsById[current.accountId] : null} />
      </main>
      {sheet && <AddSheet accounts={accounts} onClose={() => setSheet(false)} />}
    </div>
  );
}

