// Thin typed layer over the Rust commands. Components only ever talk to this.
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

export type Hue = "coral" | "sun" | "leaf" | "sky" | "grape" | "mint" | "rose" | "slate";

export interface Account {
  id: string;
  name: string;
  email: string;
  provider: "gmail" | "outlook" | "imap";
  hue: Hue;
  unread: number;
}

export type Folder = "inbox" | "starred" | "sent" | "archive";

export interface Message {
  id: number;
  accountId: string;
  folder: "inbox" | "sent";
  threadId: string;
  subject: string;
  from: { name: string; email: string };
  preview: string;
  /** Plain text body; empty in list results. */
  body: string;
  /** Sanitized HTML body; empty in list results or if the mail had none. */
  html: string;
  /** ISO timestamp. */
  date: string;
  unread: boolean;
  starred: boolean;
}

/** A conversation is identified per account; thread ids are only unique within one mailbox. */
export type ThreadRef = { accountId: string; threadId: string };
export const threadKey = (m: { accountId: string; threadId: string }) => m.accountId + "�" + m.threadId;

interface RawMessage {
  id: number;
  accountId: string;
  folder: "inbox" | "sent";
  uid: number;
  threadId: string;
  subject: string;
  fromName: string;
  fromEmail: string;
  date: number;
  snippet: string;
  textBody: string;
  htmlBody: string;
  unread: boolean;
  starred: boolean;
}

function fromRaw(r: RawMessage): Message {
  return {
    id: r.id,
    accountId: r.accountId,
    folder: r.folder,
    threadId: r.threadId,
    subject: r.subject,
    from: { name: r.fromName, email: r.fromEmail },
    preview: r.snippet,
    body: r.textBody,
    html: r.htmlBody,
    date: new Date(r.date).toISOString(),
    unread: r.unread,
    starred: r.starred,
  };
}

export interface SyncReport { accountId: string; added: number; error: string | null }

export const api = {
  listAccounts: () => invoke<Account[]>("list_accounts"),
  addGmail: (name: string, email: string, appPassword: string) =>
    invoke<Account>("add_gmail_account", { name, email, appPassword }),
  removeAccount: (accountId: string) => invoke<void>("remove_account", { accountId }),
  sync: (accountId?: string) => invoke<SyncReport[]>("sync_mail", { accountId: accountId ?? null }),
  listMessages: async (accountId?: string) =>
    (await invoke<RawMessage[]>("list_messages", { accountId: accountId ?? null })).map(fromRaw),
  getThread: async (accountId: string, threadId: string) =>
    (await invoke<RawMessage[]>("get_thread", { accountId, threadId })).map(fromRaw),
  markRead: (id: number, read: boolean) => invoke<void>("mark_read", { id, read }),
  setStarred: (id: number, starred: boolean) => invoke<void>("set_starred", { id, starred }),
  /** "archive" moves to All Mail, "trash" to Trash. */
  move: (id: number, to: "archive" | "trash") => invoke<void>("move_message", { id, to }),
  onUpdated: (cb: () => void): Promise<UnlistenFn> => listen("mail:updated", cb),
};

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { api, threadKey, type Account, type Folder, type Message, type ThreadRef } from "./api";
import { AccountRail } from "./components/AccountRail";
import { MailList, type Row } from "./components/MailList";
import { Reader } from "./components/Reader";
import { AddSheet } from "./components/AddSheet";
import { WindowControls, useMaximized, useWindowDrag } from "./components/WindowControls";
import "./styles/base.css";
import "./App.css";

/** Background poll interval while the app is open. */
const POLL_MS = 90_000;

export default function App() {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedAccount, setSelectedAccount] = useState<string | "all">("all");
  const [folder, setFolder] = useState<Folder>("inbox");
  const [selected, setSelected] = useState<ThreadRef | null>(null);
  const [thread, setThread] = useState<Message[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [sheet, setSheet] = useState(false);
  const [sheetClose, setSheetClose] = useState(0);
  const [refreshTick, setRefreshTick] = useState(0);
  const sheetRef = useRef(false);
  sheetRef.current = sheet;
  const maximized = useMaximized();
  useWindowDrag(maximized);

  // ---- data loading
  const reload = useCallback(async () => {
    const [a, m] = await Promise.all([api.listAccounts(), api.listMessages()]);
    setAccounts(a);
    setMessages(m);
  }, []);

  const sync = useCallback(async () => {
    setSyncing(true);
    try { await api.sync(); } catch { /* per-account errors are reported in the result; ignore here */ }
    finally { setSyncing(false); }
  }, []);

  useEffect(() => {
    reload();
    sync();
    const unlisten = api.onUpdated(() => reload());
    const timer = window.setInterval(sync, POLL_MS);
    return () => { unlisten.then((f) => f()); window.clearInterval(timer); };
  }, [reload, sync]);

  // Load the full conversation (with bodies) whenever the selection changes, and mark it read.
  useEffect(() => {
    if (!selected) { setThread([]); return; }
    let cancelled = false;
    api.getThread(selected.accountId, selected.threadId).then((t) => {
      if (cancelled) return;
      setThread(t);
      const unread = t.filter((m) => m.unread);
      if (unread.length) {
        unread.forEach((m) => api.markRead(m.id, true));
        setMessages((prev) => prev.map((m) => (unread.some((u) => u.id === m.id) ? { ...m, unread: false } : m)));
        setAccounts((prev) => prev.map((a) => (a.id === selected.accountId ? { ...a, unread: Math.max(0, a.unread - unread.filter((u) => u.folder === "inbox").length) } : a)));
        setThread((prev) => prev.map((m) => ({ ...m, unread: false })));
      }
    });
    return () => { cancelled = true; };
  }, [selected]);

  // ---- keys: Esc closes the sheet, then the email; F5 / Ctrl+R is a refresh, never a reload
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const inField = (e.target as HTMLElement | null)?.closest("input, textarea, [contenteditable]");
      if (e.key === "Escape") {
        if (sheetRef.current) { setSheetClose((n) => n + 1); return; }
        if (!inField) { setSelected(null); return; }
      }
      const reload = e.key === "F5" || ((e.ctrlKey || e.metaKey) && (e.key === "r" || e.key === "R"));
      const nav = e.altKey && (e.key === "ArrowLeft" || e.key === "ArrowRight");
      if (reload) {
        e.preventDefault();
        setRefreshTick((t) => t + 1);
        sync();
        return;
      }
      if (nav || e.key === "BrowserBack" || e.key === "BrowserForward") e.preventDefault();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [sync]);

  // ---- derived
  const accountsById = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a])), [accounts]);

  const scoped = useMemo(() => {
    return messages
      .filter((m) => selectedAccount === "all" || m.accountId === selectedAccount)
      .filter((m) => {
        if (folder === "starred") return m.starred;
        if (folder === "archive") return false; // not cached yet
        return m.folder === folder;
      });
  }, [messages, selectedAccount, folder]);

  const rows = useMemo<Row[]>(() => {
    const seen = new Map<string, Row>();
    for (const m of scoped) {
      const k = threadKey(m);
      const t = seen.get(k);
      if (t) { t.count += 1; t.unread ||= m.unread; }
      else seen.set(k, { latest: m, count: 1, unread: m.unread });
    }
    return [...seen.values()];
  }, [scoped]);

  const account = selected ? accountsById[selected.accountId] ?? null : null;
  const title = selectedAccount === "all" ? "All Inboxes" : accountsById[selectedAccount]?.name ?? "";

  // ---- actions on the open conversation
  const onStar = async (m: Message, starred: boolean) => {
    setThread((prev) => prev.map((x) => (x.id === m.id ? { ...x, starred } : x)));
    setMessages((prev) => prev.map((x) => (x.id === m.id ? { ...x, starred } : x)));
    await api.setStarred(m.id, starred);
  };
  const onMove = async (to: "archive" | "trash") => {
    const ids = thread.map((m) => m.id);
    setSelected(null);
    setMessages((prev) => prev.filter((m) => !ids.includes(m.id)));
    await Promise.all(ids.map((id) => api.move(id, to)));
  };

  return (
    <div className="frame" data-maximized={maximized}>
      <div className="app">
        <WindowControls maximized={maximized} />
        <AccountRail
          accounts={accounts}
          selected={selectedAccount}
          onSelect={setSelectedAccount}
          onAdd={() => setSheet(true)}
        />
        <main className="main">
          <MailList
            viewKey={selectedAccount + ":" + folder + ":" + refreshTick}
            title={title}
            syncing={syncing}
            accountsById={accountsById}
            rows={rows}
            folder={folder}
            onFolder={setFolder}
            selectedKey={selected ? threadKey(selected) : null}
            onSelect={(m) => setSelected({ accountId: m.accountId, threadId: m.threadId })}
            showAccountChip={selectedAccount === "all"}
            hasAccounts={accounts.length > 0}
            onAdd={() => setSheet(true)}
          />
          <Reader thread={thread} account={account} onStar={onStar} onMove={onMove} />
        </main>
        {sheet && (
          <AddSheet
            accounts={accounts}
            closeSignal={sheetClose}
            onClose={() => { setSheet(false); setSheetClose(0); }}
            onAdded={() => reload()}
          />
        )}
      </div>
    </div>
  );
}

import { Search, Star, PenLine, Loader2, Plus } from "lucide-react";
import type { Account, Folder, Message } from "../api";
import { threadKey } from "../api";
import "./MailList.css";

export interface Row { latest: Message; count: number; unread: boolean }

interface Props {
  /** Changes whenever the account or folder changes; remounts the rows so they always animate in. */
  viewKey: string;
  title: string;
  syncing: boolean;
  accountsById: Record<string, Account>;
  rows: Row[];
  folder: Folder;
  onFolder: (f: Folder) => void;
  selectedKey: string | null;
  onSelect: (m: Message) => void;
  showAccountChip: boolean;
  hasAccounts: boolean;
  onAdd: () => void;
}

const folders: { id: Folder; label: string }[] = [
  { id: "inbox", label: "Inbox" },
  { id: "starred", label: "Starred" },
  { id: "sent", label: "Sent" },
  { id: "archive", label: "Archive" },
];

export function relTime(iso: string) {
  const d = new Date(iso);
  const diff = (Date.now() - d.getTime()) / 60000;
  if (diff < 1) return "now";
  if (diff < 60) return Math.round(diff) + "m";
  if (diff < 60 * 24) return Math.round(diff / 60) + "h";
  if (diff < 60 * 24 * 7) return Math.round(diff / 1440) + "d";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

export function MailList({ viewKey, title, syncing, accountsById, rows, folder, onFolder, selectedKey, onSelect, showAccountChip, hasAccounts, onAdd }: Props) {
  return (
    <section className="list">
      <header className="list-head">
        <div className="list-title-row">
          <h1 className="list-title">{title}</h1>
          <div className="list-title-actions">
            {syncing && <Loader2 size={16} className="list-spin" />}
            <button className="icon-btn" title="New message">
              <PenLine size={18} />
            </button>
          </div>
        </div>
        <label className="search">
          <Search size={16} />
          <input placeholder="Search all mail" />
        </label>
        <div className="folders">
          {folders.map((f) => (
            <button key={f.id} className="pill" data-active={folder === f.id} onClick={() => onFolder(f.id)}>
              {f.label}
            </button>
          ))}
        </div>
      </header>

      <div className="list-scroll" key={viewKey}>
        {!hasAccounts && (
          <div className="list-empty">
            <p>No accounts yet.</p>
            <button className="list-empty-btn" onClick={onAdd}><Plus size={16} /> Connect Gmail</button>
          </div>
        )}
        {hasAccounts && rows.length === 0 && <div className="list-empty">Nothing here.</div>}
        {rows.map(({ latest: m, count, unread }) => {
          const acc = accountsById[m.accountId];
          const k = threadKey(m);
          return (
            <button key={k} className="row" data-selected={selectedKey === k} data-unread={unread} onClick={() => onSelect(m)}>
              <div className="row-body">
                <div className="row-top">
                  {unread && <span className="row-unread" aria-label="Unread" />}
                  <span className="row-from">{m.from.name}{count > 1 && <span className="row-count">{count}</span>}</span>
                  {showAccountChip && acc && (
                    <span className={"row-chip hue-" + acc.hue} title={acc.email}>{acc.name}</span>
                  )}
                  {m.starred && <Star size={13} className="row-star" fill="currentColor" />}
                  <span className="row-time">{relTime(m.date)}</span>
                </div>
                <div className="row-subject">{m.subject}</div>
                <div className="row-preview">{m.preview}</div>
              </div>
            </button>
          );
        })}
      </div>
    </section>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { Archive, Reply, Star, Trash2, MailOpen, Forward, ChevronDown } from "lucide-react";
import type { Account, Message } from "../api";
import { Avatar } from "./Avatar";
import { relTime } from "./MailList";
import "./Reader.css";

interface Props {
  /** All messages in the open conversation, newest first. */
  thread: Message[];
  account: Account | null;
  onStar: (m: Message, starred: boolean) => void;
  onMove: (to: "archive" | "trash") => void;
}

/** Plain-text bodies longer than this start clipped with a "Show more" control. */
const CLIP_CHARS = 420;

export function Reader({ thread, account, onStar, onMove }: Props) {
  const newest = thread[0];
  const [open, setOpen] = useState<Set<number>>(new Set());
  useEffect(() => {
    setOpen(new Set(newest ? [newest.id] : []));
  }, [newest?.accountId, newest?.threadId]);

  if (!newest || !account) {
    return (
      <section className="reader reader-empty">
        <div className="reader-empty-art">
          <MailOpen size={38} strokeWidth={1.6} />
        </div>
        <p>Pick a message to read it here.</p>
      </section>
    );
  }

  const toggle = (id: number) =>
    setOpen((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const primary = newest.from;
  const anyStarred = thread.some((m) => m.starred);

  return (
    <section className="reader">
      <header className="reader-bar">
        <div className={"reader-account hue-" + account.hue}>
          <Avatar name={account.name} hue={account.hue} size={22} />
          <span>{account.email}</span>
        </div>
        <div className="reader-actions">
          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
          <button className="icon-btn" title={anyStarred ? "Unstar" : "Star"} data-on={anyStarred} onClick={() => onStar(newest, !anyStarred)}>
            <Star size={18} fill={anyStarred ? "currentColor" : "none"} />
          </button>
          <button className="icon-btn" title="Archive" onClick={() => onMove("archive")}><Archive size={18} /></button>
          <button className="icon-btn" title="Delete" onClick={() => onMove("trash")}><Trash2 size={18} /></button>
        </div>
      </header>

      <div className="thread">
        <div className="thread-head">
          <h2 className="reader-subject">{newest.subject}</h2>
          <div className="thread-from">
            <Avatar name={primary.name} hue={account.hue} size={40} />
            <div className="thread-from-text">
              <div className="thread-from-name">{primary.name}</div>
              <div className="thread-from-email">{primary.email}</div>
            </div>
            {thread.length > 1 && <span className="thread-count">{thread.length} messages</span>}
          </div>
        </div>

        {thread.map((m) => (
          <MessageCard
            key={m.id}
            message={m}
            showSender={m.from.email !== primary.email}
            hue={account.hue}
            expanded={open.has(m.id)}
            onToggle={() => toggle(m.id)}
          />
        ))}
      </div>
    </section>
  );
}

interface CardProps {
  message: Message;
  showSender: boolean;
  hue: Account["hue"];
  expanded: boolean;
  onToggle: () => void;
}

const CLIP_HEIGHT = "9.5em";

function MessageCard({ message: m, showSender, hue, expanded, onToggle }: CardProps) {
  const [showAll, setShowAll] = useState(false);
  const isHtml = m.html.length > 0;
  const long = !isHtml && m.body.length > CLIP_CHARS;
  const bodyRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el || !long) return;
    el.style.maxHeight = showAll ? el.scrollHeight + "px" : CLIP_HEIGHT;
  }, [showAll, long]);
  const date = new Date(m.date);
  const fullDate =
    date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) +
    " · " +
    date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });

  return (
    <article className="msg" data-expanded={expanded}>
      <button className="msg-head" onClick={onToggle}>
        {showSender && <Avatar name={m.from.name} hue={hue} size={28} />}
        <div className="msg-who">
          {showSender && <span className="msg-name">{m.from.name}</span>}
          {expanded
            ? <span className="msg-when">{fullDate}</span>
            : <span className="msg-snippet">{m.preview}</span>}
        </div>
        <span className="msg-when">{relTime(m.date)}</span>
        <ChevronDown size={16} className="msg-chevron" />
      </button>

      <div className="msg-collapse" aria-hidden={!expanded}>
        <div>
          <div className="msg-body-wrap" data-clipped={long && !showAll}>
            {isHtml
              ? (expanded ? <HtmlBody html={m.html} /> : null)
              : <div className="msg-body" ref={bodyRef} data-long={long}>{m.body}</div>}
            {long && (
              <button className="msg-more" onClick={() => setShowAll((v) => !v)} tabIndex={expanded ? 0 : -1}>
                {showAll ? "Show less" : "Show more"}
              </button>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

/** Renders sanitized email HTML in an isolated, script-free frame sized to its content. */
function HtmlBody({ html }: { html: string }) {
  const ref = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(120);
  const doc =
    "<!doctype html><html><head><meta charset='utf-8'><base target='_blank'>" +
    "<style>" +
    "@font-face{font-family:Poppins;font-weight:400;src:url('/fonts/poppins-400.woff2') format('woff2')}" +
    "@font-face{font-family:Poppins;font-weight:600;src:url('/fonts/poppins-600.woff2') format('woff2')}" +
    "html,body{margin:0;padding:0;background:transparent}" +
    "body{font-family:Poppins,'Segoe UI',sans-serif;font-size:14px;line-height:1.55;color:#ece7df;overflow-wrap:anywhere}" +
    "img{max-width:100%;height:auto} a{color:#8fb4ff} table{max-width:100%}" +
    "</style></head><body>" + html + "</body></html>";

  const fit = () => {
    const d = ref.current?.contentDocument;
    if (d) setHeight(Math.min(20000, Math.max(40, d.documentElement.scrollHeight)));
  };
  useEffect(() => {
    // Images finish loading after onload; re-measure a couple of times.
    const t1 = window.setTimeout(fit, 300);
    const t2 = window.setTimeout(fit, 1500);
    return () => { window.clearTimeout(t1); window.clearTimeout(t2); };
  }, [html]);

  return (
    <iframe
      ref={ref}
      className="msg-html"
      title="Message"
      sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox"
      srcDoc={doc}
      style={{ height }}
      onLoad={fit}
    />
  );
}

import { useEffect, useState } from "react";
import { X, Link2, Mail, ArrowRight, ShieldCheck, ArrowLeft, Loader2, ExternalLink } from "lucide-react";
import { api, type Account } from "../api";
import { Avatar } from "./Avatar";
import { ProviderMark } from "./ProviderMark";
import "./AddSheet.css";

interface Props {
  accounts: Account[];
  onClose: () => void;
  onAdded: () => void;
  /** Bump to ask the sheet to close (with its exit animation). */
  closeSignal: number;
}

type Tab = "signin" | "add";
type Provider = "gmail" | "outlook" | "icloud" | "imap";

function looksLikeGoogleAuth(url: string) {
  try {
    const u = new URL(url.trim());
    return u.hostname === "accounts.google.com" && u.pathname.includes("/o/oauth2");
  } catch {
    return false;
  }
}

const EXIT_MS = 200;

export function AddSheet({ accounts, onClose, onAdded, closeSignal }: Props) {
  const [closing, setClosing] = useState(false);
  const close = () => {
    if (closing) return;
    setClosing(true);
    window.setTimeout(onClose, EXIT_MS);
  };
  useEffect(() => { if (closeSignal > 0) close(); }, [closeSignal]);

  const [tab, setTab] = useState<Tab>(accounts.length ? "signin" : "add");
  const [url, setUrl] = useState("");
  const [picked, setPicked] = useState<string | null>(null);
  const valid = looksLikeGoogleAuth(url);
  const google = accounts.filter((a) => a.provider === "gmail");

  // add-account form
  const [provider, setProvider] = useState<Provider | null>(null);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submit = async () => {
    if (busy) return;
    setBusy(true);
    setError(null);
    try {
      await api.addGmail(name, email, password);
      onAdded();
      close();
    } catch (e) {
      setError(String(e));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="sheet-backdrop" data-closing={closing} onMouseDown={(e) => e.target === e.currentTarget && close()}>
      <div className="sheet" data-closing={closing} role="dialog" aria-modal>
        <header className="sheet-head">
          <div className="sheet-tabs">
            <button className="pill" data-active={tab === "signin"} onClick={() => setTab("signin")}>
              <ShieldCheck size={15} /> Sign in with Google
            </button>
            <button className="pill" data-active={tab === "add"} onClick={() => setTab("add")}>
              <Mail size={15} /> Add account
            </button>
          </div>
          <button className="icon-btn" onClick={close} title="Close"><X size={18} /></button>
        </header>

        {tab === "signin" && (
          <div className="sheet-body" key="signin">
            <h2 className="sheet-title">Which account should sign in?</h2>
            <p className="sheet-hint">
              Paste the Google sign-in link a site or app just opened. UniMail finishes the login with the account you pick and
              hands the result back to your browser, so nothing else changes.
            </p>
            <label className="sheet-field" data-valid={url ? valid : undefined}>
              <Link2 size={16} />
              <input
                autoFocus
                placeholder="https://accounts.google.com/o/oauth2/..."
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                spellCheck={false}
              />
