import { useEffect, useState } from "react";
import type { Hue } from "../api";

/** Personal mailbox domains: no company icon to show, fall back to the initial. */
const GENERIC = new Set([
  "gmail.com", "googlemail.com", "outlook.com", "hotmail.com", "live.com", "msn.com", "yahoo.com", "ymail.com",
  "icloud.com", "me.com", "mac.com", "aol.com", "proton.me", "protonmail.com", "mail.ru", "yandex.ru", "yandex.com",
  "gmx.com", "gmx.de", "web.de", "zoho.com", "fastmail.com", "hey.com",
]);

/** Icon URL for a sender's domain, or null for personal mailboxes. */
export function senderIcon(email: string): string | null {
  const domain = email.split("@")[1]?.toLowerCase();
  if (!domain || GENERIC.has(domain)) return null;
  // strip common mail subdomains so "email.steampowered.com" resolves to the brand
  const parts = domain.split(".");
  const root = parts.length > 2 ? parts.slice(-2).join(".") : domain;
  return "https://icons.duckduckgo.com/ip3/" + root + ".ico";
}

interface Props {
  name: string;
  hue: Hue;
  size?: number;
  /** Optional image; falls back to the initial if it fails to load. */
  src?: string | null;
}

export function Avatar({ name, hue, size = 40, src }: Props) {
  const initial = name.trim().charAt(0).toUpperCase();
  const [failed, setFailed] = useState(false);
  useEffect(() => setFailed(false), [src]);
  const showImg = !!src && !failed;
  return (
    <div
      className={"avatar hue-" + hue}
      data-img={showImg}
      style={{ width: size, height: size, fontSize: size * 0.44 }}
      aria-hidden
    >
      {showImg ? <img src={src!} alt="" onError={() => setFailed(true)} draggable={false} /> : initial}
    </div>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { Inbox, Plus, Pencil, Trash2 } from "lucide-react";
import type { Account, Hue } from "../api";
import { Avatar } from "./Avatar";
import "./AccountRail.css";

const HUES: Hue[] = ["coral", "sun", "leaf", "sky", "grape", "mint", "rose", "slate"];

interface Props {
  accounts: Account[];
  selected: string | "all";
  onSelect: (id: string | "all") => void;
  onAdd: () => void;
  onRename: (id: string) => void;
  onHue: (id: string, hue: Hue) => void;
  onRemove: (id: string) => void;
}

interface Menu { id: string; x: number; y: number }

export function AccountRail({ accounts, selected, onSelect, onAdd, onRename, onHue, onRemove }: Props) {
  const totalUnread = accounts.reduce((n, a) => n + a.unread, 0);
  const listRef = useRef<HTMLDivElement>(null);
  const [glideY, setGlideY] = useState<number | null>(null);
  const [menu, setMenu] = useState<Menu | null>(null);

  // The highlight is one element that slides to whichever tile is selected.
  useLayoutEffect(() => {
    const el = listRef.current?.querySelector<HTMLElement>('[data-id="' + selected + '"]');
    setGlideY(el ? el.offsetTop : null);
  }, [selected, accounts.length]);

  // Close the context menu on any outside press or Escape.
  useEffect(() => {
    if (!menu) return;
    const close = () => setMenu(null);
    const key = (e: KeyboardEvent) => e.key === "Escape" && close();
    window.addEventListener("mousedown", close);
    window.addEventListener("keydown", key);
    return () => { window.removeEventListener("mousedown", close); window.removeEventListener("keydown", key); };
  }, [menu]);

  const menuAccount = menu ? accounts.find((a) => a.id === menu.id) : null;

  return (
    <nav className="rail">
      <div className="rail-list" ref={listRef}>
        {glideY !== null && <span className="rail-glide" style={{ transform: "translateY(" + glideY + "px)" }} />}

        <button className="rail-item" data-id="all" data-active={selected === "all"} onClick={() => onSelect("all")} title="All Inboxes">
          <Inbox size={36} strokeWidth={2.2} className="rail-all" />
          {totalUnread > 0 && <span className="rail-badge">{totalUnread > 99 ? "99+" : totalUnread}</span>}
        </button>

        {accounts.map((a) => (
          <button
            key={a.id}
            className="rail-item"
            data-id={a.id}
            data-active={selected === a.id}
            onClick={() => onSelect(a.id)}
            onContextMenu={(e) => { e.preventDefault(); setMenu({ id: a.id, x: e.clientX, y: e.clientY }); }}
            title={a.name + " · " + a.email}
          >
            <Avatar name={a.name} hue={a.hue} size={36} />
            {a.unread > 0 && <span className="rail-badge">{a.unread > 99 ? "99+" : a.unread}</span>}
          </button>
        ))}

        <button className="rail-item rail-add" onClick={onAdd} title="Add account or sign in with Google">
          <Plus size={52} strokeWidth={2} className="rail-plus" />
        </button>
      </div>

      {menu && menuAccount && (
        <div className="ctx" style={{ left: menu.x, top: menu.y }} onMouseDown={(e) => e.stopPropagation()}>
          <div className="ctx-title">{menuAccount.email}</div>
          <div className="ctx-hues">
            {HUES.map((h) => (
              <button
                key={h}
                className={"ctx-hue hue-" + h}
                data-on={menuAccount.hue === h}
                title={h}
                onClick={() => { onHue(menuAccount.id, h); }}
              />
            ))}
          </div>
          <button className="ctx-item" onClick={() => { setMenu(null); onRename(menuAccount.id); }}>
            <Pencil size={14} /> Rename
          </button>
          <button className="ctx-item ctx-danger" onClick={() => { setMenu(null); onRemove(menuAccount.id); }}>
            <Trash2 size={14} /> Remove account
          </button>
        </div>
      )}
    </nav>
  );
}

import { useEffect, useRef, useState } from "react";
import { Search, Star, Pencil, Loader2, Plus, Check } from "lucide-react";
import type { Account, Folder, Message } from "../api";
import "./MailList.css";

export interface Row { key: string; latest: Message; count: number; unread: boolean }

interface Props {
  /** Changes whenever the account or folder changes; remounts the rows so they always animate in. */
  viewKey: string;
  title: string;
  syncing: boolean;
  accountsById: Record<string, Account>;
  rows: Row[];
  folder: Folder;
  onFolder: (f: Folder) => void;
  selectedKey: string | null;
  onSelect: (row: Row) => void;
  showAccountChip: boolean;
  hasAccounts: boolean;
  onAdd: () => void;
  /** Set when a single account is selected: lets the header rename it. */
  renameTarget: { id: string; name: string } | null;
  renameSignal: number;
  onRename: (id: string, name: string) => void;
}

const folders: { id: Folder; label: string }[] = [
  { id: "inbox", label: "Inbox" },
  { id: "starred", label: "Starred" },
  { id: "sent", label: "Sent" },
  { id: "archive", label: "Archive" },
];

export function relTime(iso: string) {
  const d = new Date(iso);
  const diff = (Date.now() - d.getTime()) / 60000;
  if (diff < 1) return "now";
  if (diff < 60) return Math.round(diff) + "m";
  if (diff < 60 * 24) return Math.round(diff / 60) + "h";
  if (diff < 60 * 24 * 7) return Math.round(diff / 1440) + "d";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

export function MailList(props: Props) {
  const { viewKey, title, syncing, accountsById, rows, folder, onFolder, selectedKey, onSelect, showAccountChip, hasAccounts, onAdd, renameTarget, renameSignal, onRename } = props;
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const startEdit = () => {
    if (!renameTarget) return;
    setDraft(renameTarget.name);
    setEditing(true);
  };
  useEffect(() => { if (renameSignal > 0) startEdit(); }, [renameSignal]);
  useEffect(() => { setEditing(false); }, [renameTarget?.id]);
  useEffect(() => { if (editing) { inputRef.current?.focus(); inputRef.current?.select(); } }, [editing]);

  const commit = () => {
    setEditing(false);
    if (renameTarget && draft.trim() && draft.trim() !== renameTarget.name) onRename(renameTarget.id, draft.trim());
  };

  return (
    <section className="list">
      <header className="list-head">
        <div className="list-title-row">
          {editing ? (
            <input
              ref={inputRef}
              className="list-title-input"
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") commit(); if (e.key === "Escape") setEditing(false); }}
              onBlur={commit}
              maxLength={40}
            />
          ) : (
            <h1 className="list-title">{title}</h1>
          )}
          <div className="list-title-actions">
            {syncing && <Loader2 size={16} className="list-spin" />}
            {renameTarget && !editing && (
              <button className="icon-btn" title="Rename this account" onClick={startEdit}><Pencil size={17} /></button>
            )}
            {editing && (
              <button className="icon-btn" title="Save" onMouseDown={(e) => e.preventDefault()} onClick={commit}><Check size={18} /></button>
            )}
          </div>
        </div>
        <label className="search">
          <Search size={16} />
          <input placeholder="Search all mail" />
        </label>
        <div className="folders">
          {folders.map((f) => (
            <button key={f.id} className="pill" data-active={folder === f.id} onClick={() => onFolder(f.id)}>
              {f.label}
            </button>
          ))}
        </div>
      </header>

      <div className="list-scroll" key={viewKey}>
        {!hasAccounts && (
          <div className="list-empty">
            <p>No accounts yet.</p>
            <button className="list-empty-btn" onClick={onAdd}><Plus size={16} /> Add an account</button>
          </div>
        )}
        {hasAccounts && rows.length === 0 && <div className="list-empty">Nothing here.</div>}
        {rows.map((row) => {
          const { latest: m, count, unread, key } = row;
          const acc = accountsById[m.accountId];
          return (
            <button key={key} className="row" data-selected={selectedKey === key} data-unread={unread} onClick={() => onSelect(row)}>
              <div className="row-body">
                <div className="row-top">
                  {unread && <span className="row-unread" aria-label="Unread" />}
                  <span className="row-from">{m.from.name}{count > 1 && <span className="row-count">{count}</span>}</span>
                  {showAccountChip && acc && (
                    <span className={"row-chip hue-" + acc.hue} title={acc.email}>{acc.name}</span>
                  )}
                  {m.starred && <Star size={13} className="row-star" fill="currentColor" />}
                  <span className="row-time">{relTime(m.date)}</span>
                </div>
                <div className="row-subject">{m.subject}</div>
                <div className="row-preview">{m.preview}</div>
              </div>
            </button>
          );
        })}
      </div>
    </section>
  );
}

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { Archive, Reply, Star, Trash2, MailOpen, Forward, ChevronDown } from "lucide-react";
import type { Account, Message } from "../api";
import { Avatar, senderIcon } from "./Avatar";
import { relTime } from "./MailList";
import "./Reader.css";

interface Props {
  /** All messages in the open conversation, newest first. */
  thread: Message[];
  account: Account | null;
  onStar: (m: Message, starred: boolean) => void;
  onMove: (to: "archive" | "trash") => void;
}

/** Plain-text bodies longer than this start clipped with a "Show more" control. */
const CLIP_CHARS = 420;

export function Reader({ thread, account, onStar, onMove }: Props) {
  const newest = thread[0];
  const [open, setOpen] = useState<Set<number>>(new Set());
  useEffect(() => {
    setOpen(new Set(newest ? [newest.id] : []));
  }, [newest?.accountId, newest?.from.email, newest?.threadId]);

  if (!newest || !account) {
    return (
      <section className="reader reader-empty">
        <div className="reader-empty-art">
          <MailOpen size={38} strokeWidth={1.6} />
        </div>
        <p>Pick a message to read it here.</p>
      </section>
    );
  }

  const toggle = (id: number) =>
    setOpen((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const primary = newest.from;
  const anyStarred = thread.some((m) => m.starred);

  return (
    <section className="reader">
      <header className="reader-bar">
        <div className={"reader-account hue-" + account.hue}>
          <Avatar name={account.name} hue={account.hue} size={22} />
          <span>{account.email}</span>
        </div>
        <div className="reader-actions">
          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
          <button className="icon-btn" title={anyStarred ? "Unstar" : "Star"} data-on={anyStarred} onClick={() => onStar(newest, !anyStarred)}>
            <Star size={18} fill={anyStarred ? "currentColor" : "none"} />
          </button>
          <button className="icon-btn" title="Archive" onClick={() => onMove("archive")}><Archive size={18} /></button>
          <button className="icon-btn" title="Delete" onClick={() => onMove("trash")}><Trash2 size={18} /></button>
        </div>
      </header>

      <div className="thread">
        <div className="thread-head">
          <div className="thread-from">
            <Avatar name={primary.name} hue={account.hue} size={44} src={senderIcon(primary.email)} />
            <div className="thread-from-text">
              <div className="thread-from-name">{primary.name}</div>
              <div className="thread-from-email">{primary.email}</div>
            </div>
            {thread.length > 1 && <span className="thread-count">{thread.length} messages</span>}
          </div>
        </div>

        {thread.map((m) => (
          <MessageCard key={m.id} message={m} expanded={open.has(m.id)} onToggle={() => toggle(m.id)} />
        ))}
      </div>
    </section>
  );
}

interface CardProps {
  message: Message;
  expanded: boolean;
  onToggle: () => void;
}

const CLIP_HEIGHT = "9.5em";

function MessageCard({ message: m, expanded, onToggle }: CardProps) {
  const [showAll, setShowAll] = useState(false);
  const isHtml = m.html.length > 0;
  const long = !isHtml && m.body.length > CLIP_CHARS;
  const bodyRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el || !long) return;
    el.style.maxHeight = showAll ? el.scrollHeight + "px" : CLIP_HEIGHT;
  }, [showAll, long]);
  const date = new Date(m.date);
  const fullDate =
    date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) +
    " · " +
    date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });

  return (
    <article className="msg" data-expanded={expanded}>
      <button className="msg-head" onClick={onToggle}>
        <div className="msg-who">
          <span className="msg-subject">{m.subject}</span>
          {expanded
            ? <span className="msg-when">{fullDate}</span>
            : <span className="msg-snippet">{m.preview}</span>}
        </div>
        <span className="msg-when">{relTime(m.date)}</span>
        <ChevronDown size={16} className="msg-chevron" />
      </button>

      <div className="msg-collapse" aria-hidden={!expanded}>
        <div>
          <div className="msg-body-wrap" data-clipped={long && !showAll}>
            {isHtml
              ? (expanded ? <HtmlBody html={m.html} /> : null)
              : <div className="msg-body" ref={bodyRef} data-long={long}>{m.body}</div>}
            {long && (
              <button className="msg-more" onClick={() => setShowAll((v) => !v)} tabIndex={expanded ? 0 : -1}>
                {showAll ? "Show less" : "Show more"}
              </button>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

/** Rough luminance of a CSS hex color, 0 (black) to 1 (white). */
function lum(hex: string): number {
  let h = hex.replace("#", "");
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
}

/** True when the email was designed light (the common case) and should be inverted for dark mode. */
function designedLight(html: string): boolean {
  const colors = [...html.matchAll(/(?:background(?:-color)?\s*:\s*|bgcolor\s*=\s*["']?)(#[0-9a-fA-F]{3,6})/g)]
    .map((m) => m[1])
    .slice(0, 12);
  if (colors.length === 0) return true;
  const lums = colors.map(lum).sort((a, b) => a - b);
  return lums[Math.floor(lums.length / 2)] > 0.45;
}

/** Renders sanitized email HTML in an isolated, script-free frame sized to its content. */
function HtmlBody({ html }: { html: string }) {
  const ref = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(120);
  const invert = useMemo(() => designedLight(html), [html]);

  const doc =
    "<!doctype html><html><head><meta charset='utf-8'>" +
    // No scripts, no frames, no forms; images and inline CSS only.
    "<meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; img-src https: http: data: cid:; style-src 'unsafe-inline'; font-src https: data:;\">" +
    "<base target='_blank'>" +
    "<style>" +
    "@font-face{font-family:Poppins;font-weight:400;src:url('/fonts/poppins-400.woff2') format('woff2')}" +
    "@font-face{font-family:Poppins;font-weight:600;src:url('/fonts/poppins-600.woff2') format('woff2')}" +
    "html{margin:0;padding:0;background:transparent}" +
    "body{margin:0;padding:0;font-family:Poppins,'Segoe UI',sans-serif;font-size:14px;line-height:1.55;overflow-wrap:anywhere;" +
    (invert
      // Dark-mode inversion: flip the page, flip images back so photos and logos keep their colors.
      ? "background:#fff;color:#111;filter:invert(0.92) hue-rotate(180deg)}" +
        "img,video,svg,[style*='background-image']{filter:invert(1) hue-rotate(180deg)}"
      : "background:transparent;color:#ece7df}") +
    "img{max-width:100%;height:auto} a{color:#2a62d0} table{max-width:100%}" +
    "</style></head><body>" + html + "</body></html>";

  const fit = () => {
    const d = ref.current?.contentDocument;
    if (d) setHeight(Math.min(20000, Math.max(40, d.documentElement.scrollHeight)));
  };
  useEffect(() => {
    // Images finish loading after onload; re-measure a couple of times.
    const t1 = window.setTimeout(fit, 300);
    const t2 = window.setTimeout(fit, 1500);
    return () => { window.clearTimeout(t1); window.clearTimeout(t2); };
  }, [html]);

  return (
    <iframe
      ref={ref}
      className="msg-html"
      title="Message"
      sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox"
      srcDoc={doc}
      style={{ height }}
      onLoad={fit}
    />
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { api, type Account, type Folder, type Hue, type Message } from "./api";
import { AccountRail } from "./components/AccountRail";
import { MailList, type Row } from "./components/MailList";
import { Reader } from "./components/Reader";
import { AddSheet } from "./components/AddSheet";
import { WindowControls, useMaximized, useWindowDrag } from "./components/WindowControls";
import "./styles/base.css";
import "./App.css";

/** Background poll interval while the app is open. */
const POLL_MS = 90_000;

/**
 * A conversation is "everything this sender sent me" in an account, like a chat with a person.
 * Sent mail has no single counterpart, so it groups by reply thread instead.
 */
type Conversation = { accountId: string; kind: "sender"; sender: string } | { accountId: string; kind: "thread"; threadId: string };
const convKey = (c: Conversation) => (c.kind === "sender" ? c.accountId + " s " + c.sender.toLowerCase() : c.accountId + " t " + c.threadId);
const convOf = (m: Message, folder: Folder): Conversation =>
  folder === "sent" ? { accountId: m.accountId, kind: "thread", threadId: m.threadId } : { accountId: m.accountId, kind: "sender", sender: m.from.email };

export default function App() {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedAccount, setSelectedAccount] = useState<string | "all">("all");
  const [folder, setFolder] = useState<Folder>("inbox");
  const [selected, setSelected] = useState<Conversation | null>(null);
  const [thread, setThread] = useState<Message[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [sheet, setSheet] = useState(false);
  const [sheetClose, setSheetClose] = useState(0);
  const [refreshTick, setRefreshTick] = useState(0);
  const [renameSignal, setRenameSignal] = useState(0);
  const sheetRef = useRef(false);
  sheetRef.current = sheet;
  const maximized = useMaximized();
  useWindowDrag(maximized);

  // ---- data loading
  const reload = useCallback(async () => {
    const [a, m] = await Promise.all([api.listAccounts(), api.listMessages()]);
    setAccounts(a);
    setMessages(m);
  }, []);

  const sync = useCallback(async () => {
    setSyncing(true);
    try { await api.sync(); } catch { /* per-account errors are reported in the result; ignore here */ }
    finally { setSyncing(false); }
  }, []);

  useEffect(() => {
    reload();
    sync();
    const unlisten = api.onUpdated(() => reload());
    const timer = window.setInterval(sync, POLL_MS);
    return () => { unlisten.then((f) => f()); window.clearInterval(timer); };
  }, [reload, sync]);

  // Load the full conversation (with bodies) whenever the selection changes, and mark it read.
  useEffect(() => {
    if (!selected) { setThread([]); return; }
    let cancelled = false;
    const load = selected.kind === "sender"
      ? api.getSenderThread(selected.accountId, selected.sender)
      : api.getThread(selected.accountId, selected.threadId);
    load.then((t) => {
      if (cancelled) return;
      const unread = t.filter((m) => m.unread);
      setThread(t.map((m) => ({ ...m, unread: false })));
      if (unread.length) {
        unread.forEach((m) => api.markRead(m.id, true));
        const ids = new Set(unread.map((u) => u.id));
        const inboxUnread = unread.filter((u) => u.folder === "inbox").length;
        setMessages((prev) => prev.map((m) => (ids.has(m.id) ? { ...m, unread: false } : m)));
        setAccounts((prev) => prev.map((a) => (a.id === selected.accountId ? { ...a, unread: Math.max(0, a.unread - inboxUnread) } : a)));
      }
    });
    return () => { cancelled = true; };
  }, [selected]);

  // ---- keys: Esc closes the sheet, then the email; F5 / Ctrl+R is a refresh, never a reload
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const inField = (e.target as HTMLElement | null)?.closest("input, textarea, [contenteditable]");
      if (e.key === "Escape") {
        if (sheetRef.current) { setSheetClose((n) => n + 1); return; }
        if (!inField) { setSelected(null); return; }
      }
      const isReload = e.key === "F5" || ((e.ctrlKey || e.metaKey) && (e.key === "r" || e.key === "R"));
      const nav = e.altKey && (e.key === "ArrowLeft" || e.key === "ArrowRight");
      if (isReload) {
        e.preventDefault();
        setRefreshTick((t) => t + 1);
        sync();
        return;
      }
      if (nav || e.key === "BrowserBack" || e.key === "BrowserForward") e.preventDefault();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [sync]);

  // ---- derived
  const accountsById = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a])) as Record<string, Account>, [accounts]);

  const scoped = useMemo(() => {
    return messages
      .filter((m) => selectedAccount === "all" || m.accountId === selectedAccount)
      .filter((m) => {
        if (folder === "starred") return m.starred;
        if (folder === "archive") return false; // not cached yet
        return m.folder === folder;
      });
  }, [messages, selectedAccount, folder]);

  const rows = useMemo<Row[]>(() => {
    const seen = new Map<string, Row>();
    for (const m of scoped) {
      const k = convKey(convOf(m, folder));
      const t = seen.get(k);
      if (t) { t.count += 1; t.unread ||= m.unread; }
      else seen.set(k, { key: k, latest: m, count: 1, unread: m.unread });
    }
    return [...seen.values()];
  }, [scoped, folder]);

  const account = selected ? accountsById[selected.accountId] ?? null : null;
  const current = selectedAccount === "all" ? null : accountsById[selectedAccount] ?? null;
  const title = selectedAccount === "all" ? "All Inboxes" : current?.name ?? "";

  // ---- actions
  const onStar = async (m: Message, starred: boolean) => {
    setThread((prev) => prev.map((x) => (x.id === m.id ? { ...x, starred } : x)));
    setMessages((prev) => prev.map((x) => (x.id === m.id ? { ...x, starred } : x)));
    await api.setStarred(m.id, starred);
  };
  const onMove = async (to: "archive" | "trash") => {
    const ids = thread.map((m) => m.id);
    setSelected(null);
    setMessages((prev) => prev.filter((m) => !ids.includes(m.id)));
    await Promise.all(ids.map((id) => api.move(id, to)));
  };
  const onRename = async (id: string, name: string) => {
    setAccounts((prev) => prev.map((a) => (a.id === id ? { ...a, name } : a)));
    await api.renameAccount(id, name);
  };
  const onHue = async (id: string, hue: Hue) => {
    setAccounts((prev) => prev.map((a) => (a.id === id ? { ...a, hue } : a)));
    await api.setAccountHue(id, hue);
  };
  const onRemove = async (id: string) => {
    if (selectedAccount === id) setSelectedAccount("all");
    if (selected?.accountId === id) setSelected(null);
    setAccounts((prev) => prev.filter((a) => a.id !== id));
    setMessages((prev) => prev.filter((m) => m.accountId !== id));
    await api.removeAccount(id);
  };

  return (
    <div className="frame" data-maximized={maximized}>
      <div className="app">
        <WindowControls maximized={maximized} />
        <AccountRail
          accounts={accounts}
          selected={selectedAccount}
          onSelect={setSelectedAccount}
          onAdd={() => setSheet(true)}
          onRename={(id) => { setSelectedAccount(id); setRenameSignal((n) => n + 1); }}
          onHue={onHue}
          onRemove={onRemove}
        />
        <main className="main">
          <MailList
            viewKey={selectedAccount + ":" + folder + ":" + refreshTick}
            title={title}
            syncing={syncing}
            accountsById={accountsById}
            rows={rows}
            folder={folder}
            onFolder={setFolder}
            selectedKey={selected ? convKey(selected) : null}
            onSelect={(row) => setSelected(convOf(row.latest, folder))}
            showAccountChip={selectedAccount === "all"}
            hasAccounts={accounts.length > 0}
            onAdd={() => setSheet(true)}
            renameTarget={current ? { id: current.id, name: current.name } : null}
            renameSignal={renameSignal}
            onRename={onRename}
          />
          <Reader thread={thread} account={account} onStar={onStar} onMove={onMove} />
        </main>
        {sheet && (
          <AddSheet
            accounts={accounts}
            closeSignal={sheetClose}
            onClose={() => { setSheet(false); setSheetClose(0); }}
            onAdded={() => reload()}
          />
        )}
      </div>
    </div>
  );
}

