// No console window, in debug builds too: the app is also launched by Windows as a browser
// handler and spawns helper processes, and a terminal popping up for those is unacceptable.
#![windows_subsystem = "windows"]

fn main() {
    unimail_lib::run()
}

import { useEffect, useState } from "react";
import { getCurrentWindow } from "@tauri-apps/api/window";
import { X } from "lucide-react";
import { api, type Account } from "../api";
import { Avatar } from "./Avatar";
import "../styles/base.css";
import "./Chooser.css";

/**
 * The account picker window. Opens when a site or app hands Windows a Google sign-in link.
 * One click on an account finishes the login as that account, no confirm step.
 */
export function Chooser({ url }: { url: string }) {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [busy, setBusy] = useState<string | null>(null);
  const win = getCurrentWindow();

  useEffect(() => {
    api.listAccounts().then((a) => setAccounts(a.filter((x) => x.provider === "gmail"))).catch(() => {});
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") win.close(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Who is asking, when the link says (redirect_uri host, or the app's own name if Google passes one).
  const asker = (() => {
    try {
      const u = new URL(url);
      const r = u.searchParams.get("redirect_uri");
      if (r) {
        const h = new URL(r).hostname;
        return h === "localhost" || h === "127.0.0.1" ? "an app on this computer" : h;
      }
    } catch { /* fall through */ }
    return null;
  })();

  const pick = async (a: Account) => {
    if (busy) return;
    setBusy(a.id);
    try {
      await api.openGoogle(a.email, url);
      win.close();
    } catch {
      setBusy(null);
    }
  };

  return (
    <div className="chooser">
      <div className="chooser-head">
        <div className="chooser-titles">
          <div className="chooser-title">Sign in with Google</div>
          <div className="chooser-sub">{asker ? "to continue to " + asker : "pick the account to use"}</div>
        </div>
        <button className="icon-btn" title="Cancel" onClick={() => win.close()}><X size={18} /></button>
      </div>

      <div className="chooser-list">
        {accounts.map((a) => (
          <button key={a.id} className="chooser-acct" data-busy={busy === a.id} onClick={() => pick(a)}>
            <Avatar name={a.name} hue={a.hue} size={40} src={a.avatar} />
            <div className="chooser-text">
              <div className="chooser-name">{a.name}</div>
              <div className="chooser-email">{a.email}</div>
            </div>
          </button>
        ))}
        {accounts.length === 0 && <div className="chooser-empty">No Gmail accounts connected yet.</div>}
      </div>

      <div className="chooser-foot">The account you pick signs in through its own saved Google session inside UniMail.</div>
    </div>
  );
}

/* The picker window is transparent and frameless; this card is the whole window. */
.chooser {
  height: 100%;
  display: flex; flex-direction: column;
  background: #1f1c1a;
  border-radius: 14px;
  box-shadow: inset 0 0 0 1px rgba(255, 245, 230, 0.12);
  overflow: hidden;
  animation: chooser-in 220ms var(--ease-spring);
}
@keyframes chooser-in { from { opacity: 0; transform: translateY(10px) scale(0.97); } }

.chooser-head { display: flex; align-items: flex-start; justify-content: space-between; padding: 22px 18px 12px 24px; }
.chooser-titles { display: flex; flex-direction: column; gap: 2px; }
.chooser-title { font-family: var(--font-display); font-size: 19px; font-weight: 700; letter-spacing: -0.02em; }
.chooser-sub { font-size: 12.5px; color: var(--ink-3); }

.chooser-list { flex: 1; overflow-y: auto; padding: 4px 12px 12px; display: flex; flex-direction: column; gap: 4px; scrollbar-width: none; }
.chooser-list::-webkit-scrollbar { display: none; }
.chooser-acct {
  display: flex; align-items: center; gap: 12px; text-align: left;
  padding: 10px 12px; border-radius: var(--r-md);
  transition: background var(--t-fast), transform var(--t-fast);
}
.chooser-acct:hover { background: #2b2825; }
.chooser-acct:active { transform: scale(0.99); }
.chooser-acct[data-busy="true"] { opacity: 0.6; }
.chooser-text { min-width: 0; }
.chooser-name { font-weight: 650; }
.chooser-email { font-size: 12px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chooser-empty { padding: 30px 12px; text-align: center; color: var(--ink-3); font-size: 13px; }

.chooser-foot { padding: 12px 24px 18px; font-size: 11.5px; color: var(--ink-3); border-top: 1px solid var(--line); }

import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { Chooser } from "./components/Chooser";

// The same bundle serves two windows: the app, and the small account picker that opens
// when a Google sign-in link arrives (index.html?chooser=<url>).
const params = new URLSearchParams(window.location.search);
const chooserUrl = params.get("chooser");

ReactDOM.createRoot(document.getElementById("root") as HTMLElement).render(
  <React.StrictMode>
    {chooserUrl ? <Chooser url={chooserUrl} /> : <App />}
  </React.StrictMode>,
);

