21	/// Hosts the Google login flow legitimately bounces through. Anything else is the site's callback.
22	fn is_google(host: &str) -> bool {
23	    const ALLOW: &[&str] = &[
24	        "google.com",
25	        "googleusercontent.com",
26	        "gstatic.com",
27	        "googleapis.com",
28	        "youtube.com",
29	        "ggpht.com",
30	        "googlevideo.com",
31	        "gvt1.com",
32	        "recaptcha.net",
33	    ];
34	    ALLOW.iter().any(|d| host == *d || host.ends_with(&format!(".{d}")))
35	}
36	
37	/// Only a site's OAuth callback leaves the window: a non-Google http(s) URL carrying an OAuth
38	/// result (`code`/`state`/`error`), a loopback address (desktop apps), or a custom scheme.
39	/// Everything else Google wanders through during sign-in stays inside.
40	fn should_bounce(u: &Url) -> bool {
41	    let scheme = u.scheme();
42	    if scheme == "about" || scheme == "blob" || scheme == "data" {
43	        return false;
44	    }
45	    if scheme != "http" && scheme != "https" {
46	        return true; // custom scheme callback, e.g. com.example.app://oauth
47	    }
48	    let host = u.host_str().unwrap_or("");
49	    if host == "localhost" || host == "127.0.0.1" || host == "[::1]" {
50	        return true;
51	    }
52	    if is_google(host) {
53	        return false;
54	    }
55	    let q = u.query().unwrap_or("");
56	    let frag = u.fragment().unwrap_or("");
57	    let looks_oauth = |s: &str| s.split('&').any(|kv| kv.starts_with("code=") || kv.starts_with("state=") || kv.starts_with("error=") || kv.starts_with("access_token=") || kv.starts_with("id_token="));
58	    looks_oauth(q) || looks_oauth(frag)
59	}
