82	#[tauri::command]
83	pub fn open_google(app: AppHandle, email: String, url: Option<String>) -> Result<(), String> {
84	    let email = email.trim().to_lowercase();
85	    let id = account_id_for(&email);
86	    let mut target = Url::parse(url.as_deref().unwrap_or(APP_PASSWORDS_URL)).map_err(|e| format!("Bad link: {e}"))?;
87	    // On an OAuth link, name the account so Google goes straight to consent instead of asking
88	    // "Choose an account" again inside a window that only has this one account anyway.
89	    if target.host_str() == Some("accounts.google.com") && target.path().contains("/o/oauth2") {
90	        let mut pairs: Vec<(String, String)> = target
91	            .query_pairs()
92	            .filter(|(k, _)| k != "login_hint" && k != "authuser")
93	            .map(|(k, v)| (k.into_owned(), v.into_owned()))
94	            .collect();
95	        pairs.push(("login_hint".into(), email.clone()));
96	        target.query_pairs_mut().clear().extend_pairs(pairs);
97	    }
98	    let target = target.to_string();
99	    profile_dir(&app, &id)?;
100	    let exe = std::env::current_exe().map_err(|e| e.to_string())?;
101	    std::process::Command::new(exe)
102	        .args(["--google", &id, &email, &target])
103	        .spawn()
104	        .map_err(|e| format!("Could not start the Google window: {e}"))?;
105	    Ok(())
106	}
